--
-- Name: assert_bay_capacity(); Type: FUNCTION; Schema: public; Owner: ebdesign_user
--

CREATE FUNCTION public.assert_bay_capacity() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_capacity NUMERIC(12,2);
    v_booked NUMERIC(12,2);
BEGIN
    IF NEW.status IN ('cancelled','no_show','completed') THEN
        RETURN NEW;
    END IF;

    SELECT capacity_kg INTO v_capacity FROM cold_storage_bays WHERE id = NEW.bay_id;

    SELECT COALESCE(SUM(quantity_kg), 0) INTO v_booked
      FROM cold_storage_bookings
     WHERE bay_id = NEW.bay_id
       AND id <> COALESCE(NEW.id, -1)
       AND status IN ('reserved','confirmed','in_use')
       AND booked_from < NEW.booked_to
       AND booked_to   > NEW.booked_from;

    IF v_booked + NEW.quantity_kg > v_capacity THEN
        RAISE EXCEPTION
          'Cold bay % over capacity for that window: % kg already booked + % kg requested exceeds % kg.',
          NEW.bay_id, v_booked, NEW.quantity_kg, v_capacity;
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION public.assert_bay_capacity() OWNER TO ebdesign_user;

--
-- Name: assert_dispatch_authorised(); Type: FUNCTION; Schema: public; Owner: ebdesign_user
--

CREATE FUNCTION public.assert_dispatch_authorised() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_gate_issuer UUID;
    v_dispatch_issuer UUID;
BEGIN
    IF NEW.gate_pass_id IS NULL OR NEW.dispatch_pass_id IS NULL THEN
        RAISE EXCEPTION
          'Dispatch of % requires BOTH a gate pass and a dispatch pass.',
          NEW.shipment_reference;
    END IF;

    SELECT issued_by INTO v_gate_issuer FROM gate_passes WHERE id = NEW.gate_pass_id;
    SELECT issued_by INTO v_dispatch_issuer FROM dispatch_passes WHERE id = NEW.dispatch_pass_id;

    IF v_gate_issuer = v_dispatch_issuer THEN
        RAISE EXCEPTION
          'Segregation of duties: the gate pass and dispatch pass for % were issued by the same user.',
          NEW.shipment_reference;
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION public.assert_dispatch_authorised() OWNER TO ebdesign_user;

--
-- Name: assert_journal_balanced(); Type: FUNCTION; Schema: public; Owner: ebdesign_user
--

CREATE FUNCTION public.assert_journal_balanced() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_entry INTEGER;
    v_status VARCHAR(20);
    v_debit NUMERIC(20,4);
    v_credit NUMERIC(20,4);
BEGIN
    v_entry := COALESCE(NEW.journal_entry_id, OLD.journal_entry_id);

    SELECT status INTO v_status FROM journal_entries WHERE id = v_entry;

    -- Drafts are allowed to be unbalanced while being built up.
    IF v_status IS DISTINCT FROM 'posted' THEN
        RETURN COALESCE(NEW, OLD);
    END IF;

    SELECT COALESCE(SUM(debit),0), COALESCE(SUM(credit),0)
      INTO v_debit, v_credit
      FROM journal_lines WHERE journal_entry_id = v_entry;

    IF v_debit <> v_credit THEN
        RAISE EXCEPTION
          'Journal entry % is unbalanced: debits %, credits %',
          v_entry, v_debit, v_credit;
    END IF;

    RETURN COALESCE(NEW, OLD);
END;
$$;


ALTER FUNCTION public.assert_journal_balanced() OWNER TO ebdesign_user;

--
-- Name: assert_period_open(); Type: FUNCTION; Schema: public; Owner: ebdesign_user
--

CREATE FUNCTION public.assert_period_open() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_period_status VARCHAR(20);
BEGIN
    IF TG_OP = 'UPDATE' AND OLD.status = 'posted' AND NEW.status = 'posted' THEN
        IF NEW.entry_date <> OLD.entry_date
           OR NEW.company_id <> OLD.company_id
           OR NEW.currency <> OLD.currency THEN
            RAISE EXCEPTION
              'Posted journal entry % is immutable; reverse it instead of editing.', OLD.id;
        END IF;
    END IF;

    IF NEW.status = 'posted' AND NEW.fiscal_period_id IS NOT NULL THEN
        SELECT status INTO v_period_status
          FROM fiscal_periods WHERE id = NEW.fiscal_period_id;
        IF v_period_status IN ('closed','locked') THEN
            RAISE EXCEPTION
              'Cannot post to fiscal period % because it is %.',
              NEW.fiscal_period_id, v_period_status;
        END IF;
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION public.assert_period_open() OWNER TO ebdesign_user;

