--
-- Name: calculate_bmi(numeric, numeric); Type: FUNCTION; Schema: public; Owner: ebdesign_user
--

CREATE FUNCTION public.calculate_bmi(weight_kg numeric, height_cm numeric) RETURNS numeric
    LANGUAGE plpgsql
    AS $$
DECLARE
    height_m DECIMAL;
    bmi DECIMAL;
BEGIN
    height_m := height_cm / 100;
    bmi := weight_kg / (height_m * height_m);
    RETURN ROUND(bmi, 2);
END;
$$;


