--
-- Name: calculate_completion_date(uuid); Type: FUNCTION; Schema: public; Owner: ebdesign_user
--

CREATE FUNCTION public.calculate_completion_date(sample_id uuid) RETURNS date
    LANGUAGE plpgsql
    AS $$
DECLARE
    turnaround_days INTEGER;
    expected_date DATE;
BEGIN
    SELECT COALESCE(SUM(tm.turnaround_days), 7) INTO turnaround_days
    FROM sample_registrations sr
    CROSS JOIN LATERAL jsonb_array_elements_text(sr.requested_tests) AS test_id
    LEFT JOIN test_methods tm ON tm.id::TEXT = test_id
    WHERE sr.id = sample_id;
    
    expected_date := CURRENT_DATE + COALESCE(turnaround_days, 7);
    RETURN expected_date;
END;
$$;


ALTER FUNCTION public.calculate_completion_date(sample_id uuid) OWNER TO ebdesign_user;

--
-- Name: calculate_daily_health_score(uuid, date); Type: FUNCTION; Schema: public; Owner: ebdesign_user
--

CREATE FUNCTION public.calculate_daily_health_score(user_id uuid, date date) RETURNS numeric
    LANGUAGE plpgsql
    AS $$
DECLARE
    score DECIMAL;
    calorie_diff DECIMAL;
    protein_g DECIMAL;
    water_ml DECIMAL;
    steps INTEGER;
    sleep_hours DECIMAL;
BEGIN
    -- Get daily analytics
    SELECT 
        total_calories_consumed,
        total_protein_g,
        water_intake_ml,
        steps_count,
        sleep_hours
    INTO calorie_diff, protein_g, water_ml, steps, sleep_hours
    FROM health_analytics
    WHERE user_id = user_id AND date = date;
    
    -- Calculate score based on targets (simplified)
    score := 50; -- Base score
    
    IF protein_g >= 50 THEN score := score + 10; END IF;
    IF water_ml >= 2000 THEN score := score + 10; END IF;
    IF steps >= 10000 THEN score := score + 15; END IF;
    IF sleep_hours >= 7 THEN score := score + 15; END IF;
    
    RETURN score;
END;
$$;


ALTER FUNCTION public.calculate_daily_health_score(user_id uuid, date date) OWNER TO ebdesign_user;

--
-- Name: calculate_gi_pricing(uuid, numeric, uuid); Type: FUNCTION; Schema: public; Owner: ebdesign_user
--

CREATE FUNCTION public.calculate_gi_pricing(product_id uuid, base_price numeric, gi_product_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    pricing_rule RECORD;
    quality_tier RECORD;
    final_premium DECIMAL;
    final_price DECIMAL;
    premium_pct DECIMAL;
    pricing_factors JSONB;
BEGIN
    -- Get active pricing rule
    SELECT * INTO pricing_rule 
    FROM gi_pricing_rules 
    WHERE gi_product_id = gi_product_id 
    AND is_active = true 
    AND (effective_date IS NULL OR effective_date <= CURRENT_DATE)
    AND (expiry_date IS NULL OR expiry_date >= CURRENT_DATE)
    LIMIT 1;
    
    IF NOT FOUND THEN
        -- Default premium if no rule found
        final_premium := base_price * 0.15;
    ELSE
        final_premium := base_price * (pricing_rule.base_premium_percentage / 100);
    END IF;
    
    final_price := base_price + final_premium;
    premium_pct := (final_premium / base_price) * 100;
    
    pricing_factors := jsonb_build_object(
        'base_price', base_price,
        'gi_premium', final_premium,
        'quality_premium', 0,
        'seasonal_adjustment', 0,
        'final_price', final_price,
        'premium_percentage', premium_pct
    );
    
    RETURN jsonb_build_object(
        'base_price', base_price,
        'gi_premium', final_premium,
        'final_price', final_price,
        'premium_percentage', premium_pct,
        'pricing_factors', pricing_factors
    );
END;
$$;


ALTER FUNCTION public.calculate_gi_pricing(product_id uuid, base_price numeric, gi_product_id uuid) OWNER TO ebdesign_user;

--
-- Name: calculate_nutrition_score(jsonb, integer); Type: FUNCTION; Schema: public; Owner: ebdesign_user
--

CREATE FUNCTION public.calculate_nutrition_score(nutrition_data jsonb, scoring_model_id integer) RETURNS numeric
    LANGUAGE plpgsql
    AS $$
DECLARE
    model_record RECORD;
    overall_score DECIMAL;
BEGIN
    SELECT * INTO model_record FROM nutrition_scoring_models WHERE id = scoring_model_id;
    
    IF NOT FOUND THEN
        RETURN 0;
    END IF;
    
    -- Simple scoring algorithm (can be enhanced)
    -- This is a placeholder - actual implementation would use the scoring_algorithm JSON
    overall_score := 50.0; -- Base score
    
    -- Add points for high protein
    IF (nutrition_data->>'PRO')::DECIMAL > 10 THEN
        overall_score := overall_score + 10;
    END IF;
    
    -- Add points for high fiber
    IF (nutrition_data->>'FIB')::DECIMAL > 5 THEN
        overall_score := overall_score + 10;
    END IF;
    
    -- Deduct points for high saturated fat
    IF (nutrition_data->>'SAT_FAT')::DECIMAL > 5 THEN
        overall_score := overall_score - 10;
    END IF;
    
    -- Ensure score is within bounds
    overall_score := GREATEST(0, LEAST(overall_score, 100));
    
    RETURN overall_score;
END;
$$;


ALTER FUNCTION public.calculate_nutrition_score(nutrition_data jsonb, scoring_model_id integer) OWNER TO ebdesign_user;

--
-- Name: calculate_overall_quality_score(jsonb); Type: FUNCTION; Schema: public; Owner: ebdesign_user
--

CREATE FUNCTION public.calculate_overall_quality_score(quality_scores jsonb) RETURNS numeric
    LANGUAGE plpgsql
    AS $$
DECLARE
    total_score DECIMAL;
    count INTEGER;
BEGIN
    SELECT SUM(score), COUNT(*) INTO total_score, count
    FROM jsonb_each_text(quality_scores) AS t(key, score);
    
    IF count = 0 THEN
        RETURN 0;
    END IF;
    
    RETURN total_score / count;
END;
$$;


ALTER FUNCTION public.calculate_overall_quality_score(quality_scores jsonb) OWNER TO ebdesign_user;

