-- Name: calculate_total_savings(uuid, date, date); Type: FUNCTION; Schema: public; Owner: ebdesign_user
--

CREATE FUNCTION public.calculate_total_savings(reu_id_param uuid, period_start_param date, period_end_param date) RETURNS numeric
    LANGUAGE plpgsql
    AS $$
DECLARE
    total_savings DECIMAL;
BEGIN
    SELECT COALESCE(SUM(total_savings), 0)
    INTO total_savings
    FROM cross_system_savings
    WHERE reu_id = reu_id_param
    AND period_start >= period_start_param
    AND period_end <= period_end_param;
    
    RETURN total_savings;
END;
$$;


