--
-- Name: calculate_value_price(numeric, numeric, character varying); Type: FUNCTION; Schema: public; Owner: ebdesign_user
--

CREATE FUNCTION public.calculate_value_price(base_price numeric, value_score numeric, value_grade character varying) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    premium_percentage DECIMAL;
    value_premium DECIMAL;
    final_price DECIMAL;
BEGIN
    -- Calculate premium based on value grade
    IF value_grade = 'A+' THEN
        premium_percentage := 25.0;
    ELSIF value_grade = 'A' THEN
        premium_percentage := 20.0;
    ELSIF value_grade = 'B+' THEN
        premium_percentage := 15.0;
    ELSIF value_grade = 'B' THEN
        premium_percentage := 10.0;
    ELSIF value_grade = 'C' THEN
        premium_percentage := 5.0;
    ELSE
        premium_percentage := 0.0;
    END IF;
    
    value_premium := base_price * (premium_percentage / 100);
    final_price := base_price + value_premium;
    
    RETURN jsonb_build_object(
        'base_price', base_price,
        'value_premium', value_premium,
        'final_price', final_price,
        'premium_percentage', premium_percentage,
        'value_grade', value_grade,
        'value_score', value_score
    );
END;
$$;


ALTER FUNCTION public.calculate_value_price(base_price numeric, value_score numeric, value_grade character varying) OWNER TO ebdesign_user;

--
-- Name: calculate_value_score(numeric, numeric, numeric, numeric, numeric, numeric); Type: FUNCTION; Schema: public; Owner: ebdesign_user
--

CREATE FUNCTION public.calculate_value_score(nutrition_score numeric, organic_score numeric, gi_score numeric, freshness_score numeric, sustainability_score numeric, quality_score numeric) RETURNS numeric
    LANGUAGE plpgsql
    AS $$
DECLARE
    overall_score DECIMAL;
BEGIN
    -- Weighted average based on value factor weights
    overall_score := 
        (nutrition_score * 0.30) +
        (organic_score * 0.20) +
        (gi_score * 0.15) +
        (freshness_score * 0.15) +
        (sustainability_score * 0.10) +
        (quality_score * 0.10);
    
    RETURN overall_score;
END;
$$;


ALTER FUNCTION public.calculate_value_score(nutrition_score numeric, organic_score numeric, gi_score numeric, freshness_score numeric, sustainability_score numeric, quality_score numeric) OWNER TO ebdesign_user;

--
-- Name: check_bucket_allocation(); Type: FUNCTION; Schema: public; Owner: ebdesign_user
--

CREATE FUNCTION public.check_bucket_allocation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    total_allocated NUMERIC;
    lot_size NUMERIC;
BEGIN
    SELECT COALESCE(SUM(allocated_kg), 0) INTO total_allocated
      FROM pricing_buckets WHERE lot_code = NEW.lot_code AND id <> COALESCE(NEW.id, -1);
    total_allocated := total_allocated + NEW.allocated_kg;

    SELECT lot_size_kg INTO lot_size FROM pricing_lots WHERE lot_code = NEW.lot_code;
    IF lot_size IS NOT NULL AND total_allocated > lot_size THEN
        RAISE EXCEPTION 'Bucket allocation (% kg) exceeds lot size (% kg) for lot %. '
                        'Selling more than exists is how a buyer who paid receives nothing.',
                        total_allocated, lot_size, NEW.lot_code;
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION public.check_bucket_allocation() OWNER TO ebdesign_user;

--
-- Name: check_device_health(uuid); Type: FUNCTION; Schema: public; Owner: ebdesign_user
--

CREATE FUNCTION public.check_device_health(device_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    last_reading TIMESTAMP;
    is_offline BOOLEAN;
    health_status VARCHAR(20);
    result JSONB;
BEGIN
    SELECT MAX(reading_timestamp) INTO last_reading
    FROM sensor_data
    WHERE device_id = device_id;
    
    -- Consider device offline if no reading in last hour
    is_offline := (last_reading IS NULL) OR (last_reading < CURRENT_TIMESTAMP - INTERVAL '1 hour');
    
    IF is_offline THEN
        health_status := 'offline';
    ELSE
        health_status := 'healthy';
    END IF;
    
    result := jsonb_build_object(
        'device_id', device_id,
        'health_status', health_status,
        'last_reading', last_reading,
        'checked_at', CURRENT_TIMESTAMP
    );
    
    RETURN result;
END;
$$;


ALTER FUNCTION public.check_device_health(device_id uuid) OWNER TO ebdesign_user;

--
-- Name: cleanup_old_audit_logs(); Type: FUNCTION; Schema: public; Owner: ebdesign_user
--

CREATE FUNCTION public.cleanup_old_audit_logs() RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- Delete logs older than 1 year, except for critical events
  DELETE FROM audit_logs
  WHERE created_at < NOW() - INTERVAL '1 year'
    AND action NOT IN ('login', 'password_change', 'permission_denied');
  
  -- Delete expired reports
  DELETE FROM audit_reports
  WHERE expires_at < NOW();
  
  -- Delete old alert logs
  DELETE FROM audit_alert_log
  WHERE triggered_at < NOW() - INTERVAL '90 days';
END;
$$;


ALTER FUNCTION public.cleanup_old_audit_logs() OWNER TO ebdesign_user;

--
-- Name: cleanup_old_iot_data(); Type: FUNCTION; Schema: public; Owner: ebdesign_user
--

CREATE FUNCTION public.cleanup_old_iot_data() RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- Delete readings older than 6 months
  DELETE FROM iot_readings
  WHERE timestamp < NOW() - INTERVAL '6 months';
  
  -- Delete old voice commands
  DELETE FROM voice_commands
  WHERE executed_at < NOW() - INTERVAL '90 days';
  
  -- Delete old AI recommendations
  DELETE FROM ai_recommendations
  WHERE created_at < NOW() - INTERVAL '30 days';
END;
$$;


