--
-- Name: create_sensor_alerts(); Type: FUNCTION; Schema: public; Owner: ebdesign_user
--

CREATE FUNCTION public.create_sensor_alerts() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Create alerts based on sensor readings
    IF NEW.ph < 6.5 OR NEW.ph > 8.5 THEN
        INSERT INTO pond_alerts (pond_id, alert_type, severity, message, value, threshold)
        SELECT ps.pond_id, 'PH', 'WARNING', 'pH level outside optimal range', NEW.ph, 7.0
        FROM pond_sensors ps WHERE ps.id = NEW.sensor_id;
    END IF;
    
    IF NEW.temperature > 32 THEN
        INSERT INTO pond_alerts (pond_id, alert_type, severity, message, value, threshold)
        SELECT ps.pond_id, 'TEMPERATURE', 'CRITICAL', 'High temperature detected', NEW.temperature, 30.0
        FROM pond_sensors ps WHERE ps.id = NEW.sensor_id;
    END IF;
    
    IF NEW.dissolved_oxygen < 5 THEN
        INSERT INTO pond_alerts (pond_id, alert_type, severity, message, value, threshold)
        SELECT ps.pond_id, 'OXYGEN', 'WARNING', 'Low dissolved oxygen', NEW.dissolved_oxygen, 5.0
        FROM pond_sensors ps WHERE ps.id = NEW.sensor_id;
    END IF;
    
    RETURN NEW;
END;
$$;


ALTER FUNCTION public.create_sensor_alerts() OWNER TO ebdesign_user;

--
-- Name: detect_language(text); Type: FUNCTION; Schema: public; Owner: ebdesign_user
--

CREATE FUNCTION public.detect_language(input_text text) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
    detected_id INTEGER;
BEGIN
    -- Simple heuristic based on character ranges
    -- In production, this would call an ML model or external API
    IF input_text ~ '[\u0900-\u097F]' THEN
        -- Devanagari script (Hindi, Marathi, Nepali, etc.)
        SELECT id INTO detected_id FROM languages WHERE iso_code = 'hi' LIMIT 1;
    ELSIF input_text ~ '[\u0980-\u09FF]' THEN
        -- Bengali script
        SELECT id INTO detected_id FROM languages WHERE iso_code = 'bn' LIMIT 1;
    ELSIF input_text ~ '[\u0A00-\u0A7F]' THEN
        -- Gurmukhi script (Punjabi)
        SELECT id INTO detected_id FROM languages WHERE iso_code = 'pun' LIMIT 1;
    ELSIF input_text ~ '[\u0B00-\u0B7F]' THEN
        -- Oriya script
        SELECT id INTO detected_id FROM languages WHERE iso_code = 'ori' LIMIT 1;
    ELSIF input_text ~ '[\u0C00-\u0C7F]' THEN
        -- Telugu script
        SELECT id INTO detected_id FROM languages WHERE iso_code = 'tel' LIMIT 1;
    ELSIF input_text ~ '[\u0C80-\u0CFF]' THEN
        -- Kannada script
        SELECT id INTO detected_id FROM languages WHERE iso_code = 'kan' LIMIT 1;
    ELSIF input_text ~ '[\u0D00-\u0D7F]' THEN
        -- Malayalam script
        SELECT id INTO detected_id FROM languages WHERE iso_code = 'mal' LIMIT 1;
    ELSIF input_text ~ '[\u0A80-\u0AFF]' THEN
        -- Gujarati script
        SELECT id INTO detected_id FROM languages WHERE iso_code = 'guj' LIMIT 1;
    ELSIF input_text ~ '[\u0B80-\u0BFF]' THEN
        -- Tamil script
        SELECT id INTO detected_id FROM languages WHERE iso_code = 'tam' LIMIT 1;
    ELSE
        -- Default to English
        SELECT id INTO detected_id FROM languages WHERE iso_code = 'en' LIMIT 1;
    END IF;
    
    RETURN COALESCE(detected_id, 1);
END;
$$;


ALTER FUNCTION public.detect_language(input_text text) OWNER TO ebdesign_user;

