--
-- Name: find_related_nodes(uuid, character varying, integer); Type: FUNCTION; Schema: public; Owner: ebdesign_user
--

CREATE FUNCTION public.find_related_nodes(node_id uuid, relationship_type character varying, max_depth integer) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    result JSONB;
BEGIN
    -- Simplified related nodes query (in production, use graph algorithms)
    SELECT jsonb_agg(jsonb_build_object(
        'id', kn.id,
        'name', kn.name,
        'type', kn.node_type,
        'properties', kn.properties,
        'relationship', kr.relationship_type,
        'confidence', kr.confidence_score
    )) INTO result
    FROM knowledge_relationships kr
    JOIN knowledge_nodes kn ON kr.target_node_id = kn.id
    WHERE kr.source_node_id = node_id
    AND (relationship_type IS NULL OR kr.relationship_type = relationship_type)
    LIMIT 50;
    
    RETURN COALESCE(result, '[]'::jsonb);
END;
$$;


