-- Name: get_conversation_summary(uuid); Type: FUNCTION; Schema: public; Owner: ebdesign_user
--

CREATE FUNCTION public.get_conversation_summary(session_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    summary JSONB;
BEGIN
    SELECT jsonb_build_object(
        'session_id', cs.id,
        'user_id', cs.user_id,
        'domain', cd.name,
        'message_count', COUNT(cm.id),
        'started_at', cs.started_at,
        'last_activity', cs.last_activity_at,
        'status', cs.status
    ) INTO summary
    FROM conversation_sessions cs
    LEFT JOIN conversation_domains cd ON cs.domain_id = cd.id
    LEFT JOIN conversation_messages cm ON cs.id = cm.session_id
    WHERE cs.id = session_id
    GROUP BY cs.id, cd.name;
    
    RETURN summary;
END;
$$;


