--
-- Name: get_translation_from_memory(text, integer, integer, character varying); Type: FUNCTION; Schema: public; Owner: ebdesign_user
--

CREATE FUNCTION public.get_translation_from_memory(source_text text, source_lang_id integer, target_lang_id integer, domain character varying DEFAULT NULL::character varying) RETURNS uuid
    LANGUAGE plpgsql
    AS $$
DECLARE
    memory_id UUID;
BEGIN
    SELECT id INTO memory_id 
    FROM translation_memory 
    WHERE source_text = source_text 
    AND source_language_id = source_lang_id 
    AND target_language_id = target_lang_id 
    AND (domain IS NULL OR translation_memory.domain = domain)
    ORDER BY confidence_score DESC, usage_count DESC
    LIMIT 1;
    
    IF FOUND THEN
        -- Update usage count
        UPDATE translation_memory 
        SET usage_count = usage_count + 1, 
            last_used_at = CURRENT_TIMESTAMP 
        WHERE id = memory_id;
    END IF;
    
    RETURN memory_id;
END;
$$;


ALTER FUNCTION public.get_translation_from_memory(source_text text, source_lang_id integer, target_lang_id integer, domain character varying) OWNER TO ebdesign_user;

