--
-- Name: trigger_audit_alerts(); Type: FUNCTION; Schema: public; Owner: ebdesign_user
--

CREATE FUNCTION public.trigger_audit_alerts() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  alert_record RECORD;
BEGIN
  -- Check for matching alerts
  FOR alert_record IN 
    SELECT id FROM audit_alerts 
    WHERE enabled = true 
      AND condition::jsonb @> jsonb_build_object(
        'action', NEW.action,
        'entity_type', NEW.entity_type
      )
  LOOP
    INSERT INTO audit_alert_log (alert_id, audit_log_id, triggered_at)
    VALUES (alert_record.id, NEW.id, NOW());
    
    UPDATE audit_alerts 
    SET last_triggered_at = NOW(),
        trigger_count = trigger_count + 1
    WHERE id = alert_record.id;
  END LOOP;
  
  RETURN NEW;
END;
$$;


