--
-- Name: update_product_rating_trigger(); Type: FUNCTION; Schema: public; Owner: ebdesign_user
--

CREATE FUNCTION public.update_product_rating_trigger() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.status = 'approved' AND (OLD.status IS NULL OR OLD.status != 'approved') THEN
    UPDATE products
    SET 
      average_rating = (
        SELECT COALESCE(AVG(rating), 0)
        FROM product_reviews
        WHERE product_id = NEW.product_id AND status = 'approved'
      ),
      review_count = (
        SELECT COUNT(*)
        FROM product_reviews
        WHERE product_id = NEW.product_id AND status = 'approved'
      )
    WHERE id = NEW.product_id;
  ELSIF NEW.status != 'approved' AND (OLD.status IS NULL OR OLD.status = 'approved') THEN
    UPDATE products
    SET 
      average_rating = (
        SELECT COALESCE(AVG(rating), 0)
        FROM product_reviews
        WHERE product_id = NEW.product_id AND status = 'approved'
      ),
      review_count = (
        SELECT COUNT(*)
        FROM product_reviews
        WHERE product_id = NEW.product_id AND status = 'approved'
      )
    WHERE id = NEW.product_id;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.update_product_rating_trigger() OWNER TO ebdesign_user;

--
-- Name: update_session_activity(uuid); Type: FUNCTION; Schema: public; Owner: ebdesign_user
--

CREATE FUNCTION public.update_session_activity(session_id uuid) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
    UPDATE conversation_sessions 
    SET last_activity_at = CURRENT_TIMESTAMP 
    WHERE id = session_id;
END;
$$;


ALTER FUNCTION public.update_session_activity(session_id uuid) OWNER TO ebdesign_user;

--
-- Name: update_sync_statistics(integer, character varying, integer, integer); Type: FUNCTION; Schema: public; Owner: ebdesign_user
--

CREATE FUNCTION public.update_sync_statistics(user_id_param integer, status_param character varying, data_size_param integer, processing_time_param integer) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
  INSERT INTO sync_statistics (user_id, date, total_sync_attempts, total_data_synced_bytes, average_sync_time_ms)
  VALUES (user_id_param, CURRENT_DATE, 1, data_size_param, processing_time_param)
  ON CONFLICT (user_id, date) 
  DO UPDATE SET 
    total_sync_attempts = sync_statistics.total_sync_attempts + 1,
    total_data_synced_bytes = sync_statistics.total_data_synced_bytes + data_size_param,
    average_sync_time_ms = (sync_statistics.average_sync_time_ms * sync_statistics.total_sync_attempts + processing_time_param) / (sync_statistics.total_sync_attempts + 1),
    successful_syncs = CASE WHEN status_param = 'success' THEN sync_statistics.successful_syncs + 1 ELSE sync_statistics.successful_syncs END,
    failed_syncs = CASE WHEN status_param = 'failed' THEN sync_statistics.failed_syncs + 1 ELSE sync_statistics.failed_syncs END,
    updated_at = NOW();
END;
$$;


ALTER FUNCTION public.update_sync_statistics(user_id_param integer, status_param character varying, data_size_param integer, processing_time_param integer) OWNER TO ebdesign_user;

