--
-- Name: update_voice_conversation_duration(); Type: FUNCTION; Schema: public; Owner: ebdesign_user
--

CREATE FUNCTION public.update_voice_conversation_duration() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  NEW.duration_seconds = EXTRACT(EPOCH FROM (COALESCE(NEW.ended_at, CURRENT_TIMESTAMP) - NEW.started_at));
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.update_voice_conversation_duration() OWNER TO ebdesign_user;

--
-- Name: update_wallet_balance(); Type: FUNCTION; Schema: public; Owner: ebdesign_user
--

CREATE FUNCTION public.update_wallet_balance() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.status = 'completed' THEN
    IF NEW.type = 'credit' THEN
      UPDATE farmer_wallets
      SET balance = balance + NEW.amount,
          updated_at = NOW()
      WHERE id = NEW.wallet_id;
    ELSIF NEW.type = 'debit' OR NEW.type = 'transfer' THEN
      UPDATE farmer_wallets
      SET balance = balance - NEW.amount,
          updated_at = NOW()
      WHERE id = NEW.wallet_id;
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.update_wallet_balance() OWNER TO ebdesign_user;

--
-- Name: verify_chain_of_custody(uuid, character varying); Type: FUNCTION; Schema: public; Owner: ebdesign_user
--

CREATE FUNCTION public.verify_chain_of_custody(product_id uuid, batch_number character varying) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    chain RECORD;
    is_complete BOOLEAN;
    result JSONB;
BEGIN
    -- Get chain of custody records
    SELECT jsonb_agg(c) INTO chain
    FROM chain_of_custody c
    WHERE c.product_id = product_id 
    AND c.batch_number = batch_number
    ORDER BY c.transfer_date ASC;
    
    -- Check if chain is complete (simplified)
    is_complete := true;
    
    result := jsonb_build_object(
        'is_complete', is_complete,
        'chain', chain,
        'verified_at', CURRENT_TIMESTAMP
    );
    
    RETURN result;
END;
$$;


ALTER FUNCTION public.verify_chain_of_custody(product_id uuid, batch_number character varying) OWNER TO ebdesign_user;

