--
-- Name: active_models_performance; Type: VIEW; Schema: public; Owner: ebdesign_user
--

CREATE VIEW public.active_models_performance AS
 SELECT pm.id,
    pm.model_name,
    pm.model_type,
    pm.model_version,
    pm.algorithm,
    pm.model_config,
    pm.training_data_source,
    pm.accuracy_score,
    pm.precision_score,
    pm.recall_score,
    pm.f1_score,
    pm.trained_at,
    pm.is_active,
    pm.created_by,
    pm.created_at,
    pm.updated_at,
    mp.accuracy_score AS latest_accuracy,
    mp.precision_score AS latest_precision,
    mp.recall_score AS latest_recall,
    mp.f1_score AS latest_f1,
    mp.evaluation_date AS last_evaluation
   FROM (public.predictive_models pm
     LEFT JOIN LATERAL ( SELECT model_performance.id,
            model_performance.model_id,
            model_performance.evaluation_date,
            model_performance.test_dataset_size,
            model_performance.accuracy_score,
            model_performance.precision_score,
            model_performance.recall_score,
            model_performance.f1_score,
            model_performance.roc_auc_score,
            model_performance.confusion_matrix,
            model_performance.classification_report,
            model_performance.performance_notes,
            model_performance.created_at
           FROM public.model_performance
          WHERE (model_performance.model_id = pm.id)
          ORDER BY model_performance.evaluation_date DESC
         LIMIT 1) mp ON (true))
  WHERE (pm.is_active = true);


ALTER TABLE public.active_models_performance OWNER TO ebdesign_user;

