--
-- Name: ai_agent_scorecard; Type: TABLE; Schema: public; Owner: ebdesign_user
--

CREATE TABLE public.ai_agent_scorecard (
    id integer NOT NULL,
    actor_id character varying(80) NOT NULL,
    period_start date NOT NULL,
    period_end date NOT NULL,
    proposals_made integer DEFAULT 0,
    proposals_actioned integer DEFAULT 0,
    outcomes_helped integer DEFAULT 0,
    outcomes_harmed integer DEFAULT 0,
    outcomes_no_effect integer DEFAULT 0,
    helpfulness_pct numeric(5,2) GENERATED ALWAYS AS (
CASE
    WHEN (((outcomes_helped + outcomes_harmed) + outcomes_no_effect) > 0) THEN (((outcomes_helped)::numeric / (((outcomes_helped + outcomes_harmed) + outcomes_no_effect))::numeric) * (100)::numeric)
    ELSE NULL::numeric
END) STORED,
    ignore_rate_pct numeric(5,2) GENERATED ALWAYS AS (
CASE
    WHEN (proposals_made > 0) THEN ((((proposals_made - proposals_actioned))::numeric / (proposals_made)::numeric) * (100)::numeric)
    ELSE NULL::numeric
END) STORED,
    mean_ape_pct numeric(12,4),
    mean_stated_confidence numeric(5,2),
    calibration_gap numeric(8,2),
    computed_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT ai_agent_scorecard_outcomes_harmed_check CHECK ((outcomes_harmed >= 0)),
    CONSTRAINT ai_agent_scorecard_outcomes_helped_check CHECK ((outcomes_helped >= 0)),
    CONSTRAINT ai_agent_scorecard_outcomes_no_effect_check CHECK ((outcomes_no_effect >= 0)),
    CONSTRAINT ai_agent_scorecard_proposals_actioned_check CHECK ((proposals_actioned >= 0)),
    CONSTRAINT ai_agent_scorecard_proposals_made_check CHECK ((proposals_made >= 0)),
    CONSTRAINT period_valid CHECK ((period_end >= period_start))
);


