    CONSTRAINT ai_invocations_input_tokens_check CHECK (((input_tokens IS NULL) OR (input_tokens >= 0))),
    CONSTRAINT ai_invocations_latency_ms_check CHECK (((latency_ms IS NULL) OR (latency_ms >= 0))),
    CONSTRAINT ai_invocations_outcome_check CHECK (((outcome)::text = ANY ((ARRAY['success'::character varying, 'error'::character varying, 'timeout'::character varying, 'refused'::character varying, 'rate_limited'::character varying, 'filtered'::character varying])::text[]))),
    CONSTRAINT ai_invocations_output_tokens_check CHECK (((output_tokens IS NULL) OR (output_tokens >= 0))),
    CONSTRAINT failed_call_has_message CHECK ((((outcome)::text = ANY ((ARRAY['success'::character varying, 'refused'::character varying])::text[])) OR (error_message IS NOT NULL))),
    CONSTRAINT fallback_states_reason CHECK (((used_fallback = false) OR (fallback_reason IS NOT NULL)))
);


