-- Name: ai_model_registry; Type: TABLE; Schema: public; Owner: ebdesign_user
--

CREATE TABLE public.ai_model_registry (
    id integer NOT NULL,
    model_key character varying(60) NOT NULL,
    display_name character varying(120) NOT NULL,
    provider character varying(60) NOT NULL,
    model_identifier character varying(120),
    capabilities text[] DEFAULT '{}'::text[] NOT NULL,
    context_window_tokens integer,
    supports_vision boolean DEFAULT false NOT NULL,
    supports_tools boolean DEFAULT false NOT NULL,
    supports_streaming boolean DEFAULT false NOT NULL,
    cost_per_1k_input_inr numeric(10,4),
    cost_per_1k_output_inr numeric(10,4),
    typical_latency_ms integer,
    data_residency character varying(20) DEFAULT 'unknown'::character varying NOT NULL,
    approved_for_pii boolean DEFAULT false NOT NULL,
    enabled boolean DEFAULT false NOT NULL,
    added_on date DEFAULT CURRENT_DATE NOT NULL,
    notes text,
    CONSTRAINT ai_model_registry_context_window_tokens_check CHECK (((context_window_tokens IS NULL) OR (context_window_tokens > 0))),
    CONSTRAINT ai_model_registry_cost_per_1k_input_inr_check CHECK (((cost_per_1k_input_inr IS NULL) OR (cost_per_1k_input_inr >= (0)::numeric))),
    CONSTRAINT ai_model_registry_cost_per_1k_output_inr_check CHECK (((cost_per_1k_output_inr IS NULL) OR (cost_per_1k_output_inr >= (0)::numeric))),
    CONSTRAINT ai_model_registry_data_residency_check CHECK (((data_residency)::text = ANY ((ARRAY['in_country'::character varying, 'offshore'::character varying, 'on_premise'::character varying, 'unknown'::character varying])::text[]))),
    CONSTRAINT ai_model_registry_typical_latency_ms_check CHECK (((typical_latency_ms IS NULL) OR (typical_latency_ms >= 0))),
    CONSTRAINT pii_needs_known_residency CHECK (((approved_for_pii = false) OR ((data_residency)::text <> 'unknown'::text)))
);


ALTER TABLE public.ai_model_registry OWNER TO ebdesign_user;

--
-- Name: TABLE ai_model_registry; Type: COMMENT; Schema: public; Owner: ebdesign_user
--

COMMENT ON TABLE public.ai_model_registry IS 'Model slots. A slot is assigned by setting provider, model_identifier, data_residency and cost, then enabling it. approved_for_pii requires a known residency — see the DPDP note in migration 058. Nothing routes to a slot until it is enabled, and v_ai_unserved_intents lists what is unreachable while slots remain empty.';


--
-- Name: COLUMN ai_model_registry.data_residency; Type: COMMENT; Schema: public; Owner: ebdesign_user
--

COMMENT ON COLUMN public.ai_model_registry.data_residency IS 'Where the model endpoint runs. Personal data of people in India sent to an offshore endpoint is a cross-border transfer under the DPDP Act 2023. Answer this before setting approved_for_pii.';


