--
-- Name: ai_outcomes; Type: TABLE; Schema: public; Owner: ebdesign_user
--

CREATE TABLE public.ai_outcomes (
    id bigint NOT NULL,
    actor_id character varying(80) NOT NULL,
    actor_kind character varying(20) DEFAULT 'effector'::character varying NOT NULL,
    signal_type character varying(80),
    severity character varying(20),
    source character varying(120),
    action character varying(80) NOT NULL,
    subject_type character varying(60),
    subject_id character varying(100),
    escalated boolean DEFAULT false NOT NULL,
    rationale text NOT NULL,
    payload jsonb,
    outcome_status character varying(20),
    outcome_value numeric(20,4),
    outcome_notes text,
    outcome_recorded_by uuid,
    outcome_recorded_at timestamp without time zone,
    reacted_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    resolution_hours numeric(10,2) GENERATED ALWAYS AS (
CASE
    WHEN (outcome_recorded_at IS NOT NULL) THEN (EXTRACT(epoch FROM (outcome_recorded_at - reacted_at)) / (3600)::numeric)
    ELSE NULL::numeric
END) STORED,
    CONSTRAINT ai_outcomes_actor_kind_check CHECK (((actor_kind)::text = ANY ((ARRAY['effector'::character varying, 'agent'::character varying, 'decision_rule'::character varying, 'value_engine'::character varying])::text[]))),
    CONSTRAINT ai_outcomes_outcome_status_check CHECK (((outcome_status IS NULL) OR ((outcome_status)::text = ANY ((ARRAY['pending'::character varying, 'helped'::character varying, 'no_effect'::character varying, 'harmed'::character varying, 'wrong_call'::character varying, 'not_actioned'::character varying, 'superseded'::character varying])::text[])))),
    CONSTRAINT judged_outcome_needs_timestamp CHECK (((outcome_status IS NULL) OR ((outcome_status)::text = 'pending'::text) OR (outcome_recorded_at IS NOT NULL))),
    CONSTRAINT negative_outcome_needs_notes CHECK ((((outcome_status)::text <> ALL ((ARRAY['harmed'::character varying, 'wrong_call'::character varying])::text[])) OR ((outcome_notes IS NOT NULL) AND (length(TRIM(BOTH FROM outcome_notes)) > 0))))
);


