--
-- Name: ai_prediction_log; Type: TABLE; Schema: public; Owner: ebdesign_user
--

CREATE TABLE public.ai_prediction_log (
    id bigint NOT NULL,
    actor_id character varying(80) NOT NULL,
    prediction_type character varying(60) NOT NULL,
    subject_type character varying(60),
    subject_id character varying(100),
    predicted_value numeric(20,4),
    predicted_label character varying(80),
    stated_confidence numeric(5,2),
    input_quality character varying(20),
    horizon_days integer,
    predicted_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    resolves_on date,
    actual_value numeric(20,4),
    actual_label character varying(80),
    resolved_at timestamp without time zone,
    ape_pct numeric(12,4) GENERATED ALWAYS AS (
CASE
    WHEN ((actual_value IS NOT NULL) AND (actual_value <> (0)::numeric)) THEN ((abs((predicted_value - actual_value)) / abs(actual_value)) * (100)::numeric)
    ELSE NULL::numeric
END) STORED,
    was_correct boolean GENERATED ALWAYS AS (
CASE
    WHEN ((actual_label IS NOT NULL) AND (predicted_label IS NOT NULL)) THEN ((actual_label)::text = (predicted_label)::text)
    ELSE NULL::boolean
END) STORED,
    CONSTRAINT ai_prediction_log_horizon_days_check CHECK (((horizon_days IS NULL) OR (horizon_days > 0))),
