    CONSTRAINT ai_resolution_rules_tolerance_pct_check CHECK ((tolerance_pct >= (0)::numeric)),
    CONSTRAINT ai_resolution_rules_truth_aggregate_check CHECK (((truth_aggregate)::text = ANY ((ARRAY['sum'::character varying, 'avg'::character varying, 'max'::character varying, 'min'::character varying, 'count'::character varying, 'first'::character varying, 'last'::character varying])::text[]))),
    CONSTRAINT ai_resolution_rules_verdict_weight_check CHECK (((verdict_weight > (0)::numeric) AND (verdict_weight <= (1)::numeric))),
    CONSTRAINT ai_resolution_rules_window_days_check CHECK (((window_days IS NULL) OR (window_days > 0))),
    CONSTRAINT proxy_cannot_claim_full_weight CHECK ((((resolution_mode)::text <> 'proxy'::text) OR (verdict_weight < 1.00)))
);


