    CONSTRAINT arp_publications_confidence_check CHECK (((confidence >= (0)::numeric) AND (confidence <= (1)::numeric))),
    CONSTRAINT arp_publications_months_ahead_check CHECK ((months_ahead > (0)::numeric)),
    CONSTRAINT arp_publications_spot_per_kg_check CHECK ((spot_per_kg > (0)::numeric)),
    CONSTRAINT band_is_ordered CHECK (((low_per_kg <= central_per_kg) AND (central_per_kg <= high_per_kg))),
    CONSTRAINT uncalibrated_publication_must_warn CHECK (((confidence >= 0.5) OR (warning IS NOT NULL)))
);


