--
-- Name: asset_depreciation_schedule; Type: TABLE; Schema: public; Owner: ebdesign_user
--

CREATE TABLE public.asset_depreciation_schedule (
    id bigint NOT NULL,
    asset_code character varying(60) NOT NULL,
    asset_name character varying(200) NOT NULL,
    project_ref character varying(60),
    capitalised_on date NOT NULL,
    gross_block_inr numeric(16,2) NOT NULL,
    salvage_value_inr numeric(16,2) DEFAULT 0 NOT NULL,
    useful_life_years numeric(5,2) NOT NULL,
    method character varying(10) DEFAULT 'SLM'::character varying NOT NULL,
    annual_depreciation_inr numeric(16,2) GENERATED ALWAYS AS (
CASE
    WHEN ((method)::text = 'SLM'::text) THEN round(((gross_block_inr - salvage_value_inr) / useful_life_years), 2)
    ELSE NULL::numeric
END) STORED,
    co_owner_id uuid,
    co_owner_share_pct numeric(5,2),
    disposed_on date,
    created_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT asset_depreciation_schedule_co_owner_share_pct_check CHECK (((co_owner_share_pct IS NULL) OR ((co_owner_share_pct > (0)::numeric) AND (co_owner_share_pct <= (100)::numeric)))),
    CONSTRAINT asset_depreciation_schedule_gross_block_inr_check CHECK ((gross_block_inr > (0)::numeric)),
    CONSTRAINT asset_depreciation_schedule_method_check CHECK (((method)::text = ANY ((ARRAY['SLM'::character varying, 'WDV'::character varying])::text[]))),
    CONSTRAINT asset_depreciation_schedule_salvage_value_inr_check CHECK ((salvage_value_inr >= (0)::numeric)),
    CONSTRAINT asset_depreciation_schedule_useful_life_years_check CHECK ((useful_life_years > (0)::numeric)),
    CONSTRAINT co_owner_has_share CHECK (((co_owner_id IS NULL) = (co_owner_share_pct IS NULL))),
    CONSTRAINT salvage_below_cost CHECK ((salvage_value_inr < gross_block_inr))
);


