    cancelled_at timestamp without time zone,
    cancellation_reason text,
    CONSTRAINT alert_states_an_action CHECK ((length(TRIM(BOTH FROM recommended_action)) > 0)),
    CONSTRAINT alert_window_valid CHECK ((effective_until >= effective_from)),
    CONSTRAINT cancelled_alert_has_reason CHECK (((cancelled_at IS NULL) OR (cancellation_reason IS NOT NULL))),
    CONSTRAINT climate_alerts_alert_type_check CHECK (((alert_type)::text = ANY ((ARRAY['heavy_rain'::character varying, 'flood'::character varying, 'landslide'::character varying, 'drought'::character varying, 'hailstorm'::character varying, 'cold_wave'::character varying, 'heat_wave'::character varying, 'cyclone'::character varying, 'earthquake'::character varying, 'frost'::character varying, 'pest_outbreak'::character varying])::text[]))),
    CONSTRAINT climate_alerts_severity_check CHECK (((severity)::text = ANY ((ARRAY['advisory'::character varying, 'watch'::character varying, 'warning'::character varying, 'severe'::character varying, 'extreme'::character varying])::text[]))),
    CONSTRAINT severe_alerts_block_or_explain CHECK ((((severity)::text <> ALL ((ARRAY['severe'::character varying, 'extreme'::character varying])::text[])) OR (blocks_dispatch = true) OR (detail IS NOT NULL)))
);


