--

CREATE TABLE public.climate_indices (
    id bigint NOT NULL,
    district character varying(80) NOT NULL,
    state character varying(60) NOT NULL,
    index_type character varying(20) NOT NULL,
    period_start date NOT NULL,
    period_end date NOT NULL,
    index_value numeric(10,4) NOT NULL,
    classification character varying(30),
    rainfall_actual_mm numeric(9,2),
    rainfall_normal_mm numeric(9,2),
    departure_pct numeric(7,2) GENERATED ALWAYS AS (
CASE
    WHEN ((rainfall_normal_mm IS NOT NULL) AND (rainfall_normal_mm <> (0)::numeric)) THEN round((((rainfall_actual_mm - rainfall_normal_mm) / rainfall_normal_mm) * (100)::numeric), 2)
    ELSE NULL::numeric
END) STORED,
    source character varying(30) DEFAULT 'computed'::character varying NOT NULL,
    computed_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT climate_indices_index_type_check CHECK (((index_type)::text = ANY ((ARRAY['spi'::character varying, 'spei'::character varying, 'ndvi'::character varying, 'ndwi'::character varying, 'flood_risk'::character varying, 'aridity'::character varying, 'gdd'::character varying])::text[]))),
    CONSTRAINT index_period_valid CHECK ((period_end >= period_start))
);


