-- Name: climate_risk_assessments; Type: TABLE; Schema: public; Owner: ebdesign_user
--

CREATE TABLE public.climate_risk_assessments (
    id bigint NOT NULL,
    subject_type character varying(20) NOT NULL,
    subject_ref character varying(80) NOT NULL,
    horizon character varying(20) DEFAULT 'season'::character varying NOT NULL,
    drought_risk numeric(4,3),
    flood_risk numeric(4,3),
    landslide_risk numeric(4,3),
    heat_stress_risk numeric(4,3),
    composite_risk numeric(4,3),
    data_provenance character varying(20) DEFAULT 'assumed'::character varying NOT NULL,
    years_of_data integer DEFAULT 0 NOT NULL,
    method text,
    assessed_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT climate_risk_assessments_composite_risk_check CHECK (((composite_risk IS NULL) OR ((composite_risk >= (0)::numeric) AND (composite_risk <= (1)::numeric)))),
    CONSTRAINT climate_risk_assessments_data_provenance_check CHECK (((data_provenance)::text = ANY ((ARRAY['real'::character varying, 'estimated'::character varying, 'assumed'::character varying])::text[]))),
    CONSTRAINT climate_risk_assessments_drought_risk_check CHECK (((drought_risk IS NULL) OR ((drought_risk >= (0)::numeric) AND (drought_risk <= (1)::numeric)))),
    CONSTRAINT climate_risk_assessments_flood_risk_check CHECK (((flood_risk IS NULL) OR ((flood_risk >= (0)::numeric) AND (flood_risk <= (1)::numeric)))),
    CONSTRAINT climate_risk_assessments_heat_stress_risk_check CHECK (((heat_stress_risk IS NULL) OR ((heat_stress_risk >= (0)::numeric) AND (heat_stress_risk <= (1)::numeric)))),
    CONSTRAINT climate_risk_assessments_horizon_check CHECK (((horizon)::text = ANY ((ARRAY['season'::character varying, 'year'::character varying, '5_year'::character varying, '10_year'::character varying])::text[]))),
    CONSTRAINT climate_risk_assessments_landslide_risk_check CHECK (((landslide_risk IS NULL) OR ((landslide_risk >= (0)::numeric) AND (landslide_risk <= (1)::numeric)))),
    CONSTRAINT climate_risk_assessments_subject_type_check CHECK (((subject_type)::text = ANY ((ARRAY['plot'::character varying, 'village'::character varying, 'district'::character varying, 'fpo'::character varying, 'lane'::character varying, 'facility'::character varying])::text[]))),
    CONSTRAINT climate_risk_assessments_years_of_data_check CHECK ((years_of_data >= 0)),
    CONSTRAINT real_risk_needs_history CHECK ((((data_provenance)::text <> 'real'::text) OR (years_of_data >= 3)))
);


