--

CREATE TABLE public.crm_opportunities (
    id integer NOT NULL,
    opportunity_code character varying(40) NOT NULL,
    lead_id integer,
    client_id integer,
    name character varying(255) NOT NULL,
    stage character varying(30) DEFAULT 'prospecting'::character varying NOT NULL,
    amount numeric(20,4) DEFAULT 0 NOT NULL,
    probability_pct numeric(5,2),
    weighted_value numeric(20,4) GENERATED ALWAYS AS (((amount * COALESCE(probability_pct, (0)::numeric)) / (100)::numeric)) STORED,
    expected_close_date date,
    owner_id uuid,
    lost_reason text,
    created_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT crm_opportunities_probability_pct_check CHECK (((probability_pct >= (0)::numeric) AND (probability_pct <= (100)::numeric))),
    CONSTRAINT crm_opportunities_stage_check CHECK (((stage)::text = ANY ((ARRAY['prospecting'::character varying, 'qualification'::character varying, 'proposal'::character varying, 'negotiation'::character varying, 'won'::character varying, 'lost'::character varying])::text[]))),
    CONSTRAINT opp_lost_needs_reason CHECK ((((stage)::text <> 'lost'::text) OR ((lost_reason IS NOT NULL) AND (length(TRIM(BOTH FROM lost_reason)) > 0))))
);


