--
-- Name: logistics_summary; Type: VIEW; Schema: public; Owner: ebdesign_user
--

CREATE VIEW public.logistics_summary AS
 SELECT logistics_orders.reu_id,
    count(*) AS total_shipments,
    sum(logistics_orders.total_cost) AS total_logistics_cost,
    avg(logistics_orders.distance_km) AS average_distance,
    count(
        CASE
            WHEN ((logistics_orders.status)::text = 'delivered'::text) THEN 1
            ELSE NULL::integer
        END) AS delivered_shipments,
    count(
        CASE
            WHEN ((logistics_orders.status)::text = 'in_transit'::text) THEN 1
            ELSE NULL::integer
        END) AS in_transit_shipments,
    sum(
        CASE
            WHEN logistics_orders.backhaul_used THEN logistics_orders.backhaul_savings
            ELSE (0)::numeric
        END) AS total_backhaul_savings
   FROM public.logistics_orders
  GROUP BY logistics_orders.reu_id;


ALTER TABLE public.logistics_summary OWNER TO ebdesign_user;

