--
-- Name: mobility_summary; Type: VIEW; Schema: public; Owner: ebdesign_user
--

CREATE VIEW public.mobility_summary AS
 SELECT mobility_rides.reu_id,
    count(*) AS total_rides,
    sum(mobility_rides.total_cost) AS total_mobility_cost,
    avg(mobility_rides.distance_km) AS average_distance,
    count(
        CASE
            WHEN ((mobility_rides.ride_type)::text = 'shared_community'::text) THEN 1
            ELSE NULL::integer
        END) AS shared_community_rides,
    count(
        CASE
            WHEN ((mobility_rides.ride_type)::text = 'shared_shuttle'::text) THEN 1
            ELSE NULL::integer
        END) AS shared_shuttle_rides,
    count(
        CASE
            WHEN ((mobility_rides.ride_type)::text = 'on_demand'::text) THEN 1
            ELSE NULL::integer
        END) AS on_demand_rides,
    avg(mobility_rides.driver_rating) AS average_driver_rating
   FROM public.mobility_rides
  GROUP BY mobility_rides.reu_id;


