--
-- Name: procurement_summary; Type: VIEW; Schema: public; Owner: ebdesign_user
--

CREATE VIEW public.procurement_summary AS
 SELECT procurement_orders.reu_id,
    count(*) AS total_orders,
    sum(procurement_orders.total_amount) AS total_spend,
    sum(procurement_orders.total_savings) AS total_savings,
    avg(procurement_orders.savings_percentage) AS average_savings_percentage,
    count(
        CASE
            WHEN ((procurement_orders.status)::text = 'delivered'::text) THEN 1
            ELSE NULL::integer
        END) AS delivered_orders,
    count(
        CASE
            WHEN ((procurement_orders.status)::text = 'pending'::text) THEN 1
            ELSE NULL::integer
        END) AS pending_orders
   FROM public.procurement_orders
  GROUP BY procurement_orders.reu_id;


ALTER TABLE public.procurement_summary OWNER TO ebdesign_user;

--
-- Name: cross_system_summary; Type: VIEW; Schema: public; Owner: ebdesign_user
--

CREATE VIEW public.cross_system_summary AS
 SELECT cs.reu_id,
    cs.total_savings,
    ps.total_spend AS procurement_spend,
    ls.total_logistics_cost,
    ms.total_mobility_cost,
    ps.total_orders AS procurement_count,
    ls.total_shipments AS logistics_count,
    ms.total_rides AS mobility_count,
    ((ps.total_spend + ls.total_logistics_cost) + ms.total_mobility_cost) AS total_spend
   FROM (((public.cross_system_savings cs
     LEFT JOIN public.procurement_summary ps ON ((ps.reu_id = cs.reu_id)))
     LEFT JOIN public.logistics_summary ls ON ((ls.reu_id = cs.reu_id)))
     LEFT JOIN public.mobility_summary ms ON ((ms.reu_id = cs.reu_id)))
  WHERE (((cs.period_type)::text = 'monthly'::text) AND (cs.period_end = ( SELECT max(cross_system_savings.period_end) AS max
           FROM public.cross_system_savings
          WHERE ((cross_system_savings.period_type)::text = 'monthly'::text))));


ALTER TABLE public.cross_system_summary OWNER TO ebdesign_user;

