    was_short boolean DEFAULT false,
    shortfall_reason text,
    status character varying(20) DEFAULT 'scheduled'::character varying NOT NULL,
    CONSTRAINT csa_deliveries_status_check CHECK (((status)::text = ANY ((ARRAY['scheduled'::character varying, 'packed'::character varying, 'delivered'::character varying, 'missed'::character varying, 'substituted'::character varying])::text[]))),
    CONSTRAINT csa_short_needs_reason CHECK (((was_short = false) OR ((shortfall_reason IS NOT NULL) AND (length(TRIM(BOTH FROM shortfall_reason)) > 0))))
);


