--
-- Name: csa_subscriptions; Type: TABLE; Schema: public; Owner: ebdesign_user
--

CREATE TABLE public.csa_subscriptions (
    id integer NOT NULL,
    subscription_code character varying(40) NOT NULL,
    subscriber_id character varying(100) NOT NULL,
    farmer_id character varying(100),
    fpo_id character varying(100),
    season character varying(40) NOT NULL,
    share_size character varying(20) DEFAULT 'full'::character varying NOT NULL,
    amount_committed numeric(20,4) NOT NULL,
    amount_paid numeric(20,4) DEFAULT 0 NOT NULL,
    delivery_frequency character varying(20) DEFAULT 'weekly'::character varying NOT NULL,
    risk_acknowledged boolean DEFAULT false NOT NULL,
    risk_acknowledged_at timestamp without time zone,
    status character varying(20) DEFAULT 'pending'::character varying NOT NULL,
    start_date date,
    end_date date,
    created_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT csa_requires_risk_ack CHECK ((((status)::text = 'pending'::text) OR (risk_acknowledged = true))),
    CONSTRAINT csa_subscriptions_amount_committed_check CHECK ((amount_committed > (0)::numeric)),
    CONSTRAINT csa_subscriptions_check CHECK ((amount_paid <= amount_committed)),
    CONSTRAINT csa_subscriptions_delivery_frequency_check CHECK (((delivery_frequency)::text = ANY ((ARRAY['weekly'::character varying, 'fortnightly'::character varying, 'monthly'::character varying])::text[]))),
    CONSTRAINT csa_subscriptions_share_size_check CHECK (((share_size)::text = ANY ((ARRAY['half'::character varying, 'full'::character varying, 'double'::character varying])::text[]))),
    CONSTRAINT csa_subscriptions_status_check CHECK (((status)::text = ANY ((ARRAY['pending'::character varying, 'active'::character varying, 'fulfilling'::character varying, 'completed'::character varying, 'cancelled'::character varying, 'crop_failed'::character varying])::text[])))
);


