--
-- Name: digital_twin_sensor_summary; Type: VIEW; Schema: public; Owner: ebdesign_user
--

CREATE VIEW public.digital_twin_sensor_summary AS
 SELECT s.id,
    s.sensor_id,
    s.sensor_name,
    s.sensor_type,
    s.sensor_category,
    s.location,
    s.status,
    p.project_number,
    p.name AS project_name,
    max(d."timestamp") AS last_reading_time,
    d.reading_value AS last_reading_value,
    d.unit
   FROM ((public.digital_twin_sensors s
     JOIN public.engineering_projects p ON ((s.project_id = p.id)))
     LEFT JOIN public.digital_twin_data d ON (((s.sensor_id)::text = (d.sensor_id)::text)))
  GROUP BY s.id, s.sensor_id, s.sensor_name, s.sensor_type, s.sensor_category, s.location, s.status, p.project_number, p.name, d.reading_value, d.unit;


