    affected_entity_type character varying(50),
    affected_entity_ids text[],
    people_at_risk boolean DEFAULT false,
    detected_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    detected_by character varying(60),
    acknowledged_at timestamp without time zone,
    acknowledged_by uuid,
    contained_at timestamp without time zone,
    resolved_at timestamp without time zone,
    incident_commander uuid,
    status character varying(20) DEFAULT 'open'::character varying NOT NULL,
    root_cause text,
    lessons_learned text,
    created_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT emergency_incidents_severity_check CHECK (((severity)::text = ANY ((ARRAY['low'::character varying, 'medium'::character varying, 'high'::character varying, 'critical'::character varying])::text[]))),
    CONSTRAINT emergency_incidents_status_check CHECK (((status)::text = ANY ((ARRAY['open'::character varying, 'acknowledged'::character varying, 'containing'::character varying, 'contained'::character varying, 'resolved'::character varying, 'post_review'::character varying, 'closed'::character varying])::text[]))),
    CONSTRAINT incident_closure_needs_review CHECK ((((status)::text <> 'closed'::text) OR ((severity)::text <> ALL ((ARRAY['high'::character varying, 'critical'::character varying])::text[])) OR ((root_cause IS NOT NULL) AND (length(TRIM(BOTH FROM root_cause)) > 0))))
);


