--
-- Name: engineering_project_summary; Type: VIEW; Schema: public; Owner: ebdesign_user
--

CREATE VIEW public.engineering_project_summary AS
 SELECT p.id,
    p.project_number,
    p.name,
    p.project_type,
    p.project_subtype,
    p.location,
    p.capacity,
    p.budget,
    p.status,
    p.phase,
    p.phase_progress,
    p.created_at,
    p.updated_at,
    up.full_name AS user_name,
    u.email AS user_email,
    f.name AS fpo_name
   FROM (((public.engineering_projects p
     LEFT JOIN public.users u ON ((p.user_id = u.id)))
     LEFT JOIN public.user_profiles up ON ((up.user_id = u.id)))
     LEFT JOIN public.fpos f ON ((p.fpo_id = f.id)))
  WHERE (p.deleted_at IS NULL);


