-- Name: enwr_receipts; Type: TABLE; Schema: public; Owner: ebdesign_user
--

CREATE TABLE public.enwr_receipts (
    id bigint NOT NULL,
    receipt_no character varying(40) NOT NULL,
    booking_id character varying(60),
    facility_id character varying(60),
    farmer_id uuid,
    commodity character varying(120),
    quantity_qtl numeric(14,3) NOT NULL,
    estimated_value_inr numeric(16,2) NOT NULL,
    haircut_pct numeric(5,2) DEFAULT 30.00 NOT NULL,
    max_collateral_inr numeric(16,2) GENERATED ALWAYS AS (round(((estimated_value_inr * ((100)::numeric - haircut_pct)) / (100)::numeric), 2)) STORED,
    valuation_basis character varying(20) DEFAULT 'estimated'::character varying NOT NULL,
    status character varying(20) DEFAULT 'issued'::character varying NOT NULL,
    pledged_to character varying(150),
    pledged_amount_inr numeric(16,2),
    issued_by uuid,
    issued_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    valid_until date,
    CONSTRAINT enwr_receipts_estimated_value_inr_check CHECK ((estimated_value_inr > (0)::numeric)),
    CONSTRAINT enwr_receipts_haircut_pct_check CHECK (((haircut_pct >= (0)::numeric) AND (haircut_pct < (100)::numeric))),
    CONSTRAINT enwr_receipts_pledged_amount_inr_check CHECK (((pledged_amount_inr IS NULL) OR (pledged_amount_inr >= (0)::numeric))),
    CONSTRAINT enwr_receipts_quantity_qtl_check CHECK ((quantity_qtl > (0)::numeric)),
    CONSTRAINT enwr_receipts_status_check CHECK (((status)::text = ANY ((ARRAY['issued'::character varying, 'pledged'::character varying, 'partially_released'::character varying, 'released'::character varying, 'cancelled'::character varying, 'expired'::character varying])::text[]))),
    CONSTRAINT enwr_receipts_valuation_basis_check CHECK (((valuation_basis)::text = ANY ((ARRAY['real'::character varying, 'estimated'::character varying, 'assumed'::character varying])::text[]))),
    CONSTRAINT pledge_within_ceiling CHECK (((pledged_amount_inr IS NULL) OR (pledged_amount_inr <= round(((estimated_value_inr * ((100)::numeric - haircut_pct)) / (100)::numeric), 2)))),
    CONSTRAINT pledged_receipt_names_lender CHECK ((((status)::text <> ALL ((ARRAY['pledged'::character varying, 'partially_released'::character varying])::text[])) OR (pledged_to IS NOT NULL)))
);


