--
-- Name: erp_sync_logs; Type: TABLE; Schema: public; Owner: ebdesign_user
--

CREATE TABLE public.erp_sync_logs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    entity_type character varying(50) NOT NULL,
    entity_id uuid NOT NULL,
    erp_type character varying(50) NOT NULL,
    operation character varying(50) NOT NULL,
    status public.sync_status DEFAULT 'pending'::public.sync_status,
    request_payload jsonb,
    response_payload jsonb,
    error_message text,
    retry_count integer DEFAULT 0,
    synced_at timestamp without time zone,
    created_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP
);


ALTER TABLE public.erp_sync_logs OWNER TO ebdesign_user;

--
-- Name: TABLE erp_sync_logs; Type: COMMENT; Schema: public; Owner: ebdesign_user
--

COMMENT ON TABLE public.erp_sync_logs IS 'ERP synchronization tracking';


--
-- Name: erp_sync_dashboard; Type: VIEW; Schema: public; Owner: ebdesign_user
--

CREATE VIEW public.erp_sync_dashboard AS
 SELECT erp_sync_logs.entity_type,
    count(*) AS total_entities,
    sum(
        CASE
            WHEN (erp_sync_logs.status = 'synced'::public.sync_status) THEN 1
            ELSE 0
        END) AS synced_entities,
    sum(
        CASE
            WHEN (erp_sync_logs.status = 'failed'::public.sync_status) THEN 1
            ELSE 0
        END) AS failed_entities,
    sum(
        CASE
            WHEN (erp_sync_logs.status = 'pending'::public.sync_status) THEN 1
            ELSE 0
        END) AS pending_entities,
    max(erp_sync_logs.synced_at) AS last_sync_time
   FROM public.erp_sync_logs
  GROUP BY erp_sync_logs.entity_type;


ALTER TABLE public.erp_sync_dashboard OWNER TO ebdesign_user;

