--
-- Name: farmer_revenue; Type: TABLE; Schema: public; Owner: ebdesign_user
--

CREATE TABLE public.farmer_revenue (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    farmer_id uuid NOT NULL,
    revenue_source character varying(30) NOT NULL,
    crop_id uuid,
    yield_actual_id uuid,
    buyer_id uuid,
    quantity_kg numeric(14,3),
    gross_amount numeric(20,4) NOT NULL,
    deduction_commission numeric(20,4) DEFAULT 0,
    deduction_transport numeric(20,4) DEFAULT 0,
    deduction_grading numeric(20,4) DEFAULT 0,
    deduction_other numeric(20,4) DEFAULT 0,
    net_amount numeric(20,4) GENERATED ALWAYS AS (((((gross_amount - COALESCE(deduction_commission, (0)::numeric)) - COALESCE(deduction_transport, (0)::numeric)) - COALESCE(deduction_grading, (0)::numeric)) - COALESCE(deduction_other, (0)::numeric))) STORED,
    price_per_kg numeric(14,4) GENERATED ALWAYS AS (
CASE
    WHEN (quantity_kg > (0)::numeric) THEN (gross_amount / quantity_kg)
    ELSE NULL::numeric
END) STORED,
    season character varying(30),
    year smallint,
    received_on date NOT NULL,
    payment_status character varying(20) DEFAULT 'received'::character varying NOT NULL,
    created_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT farmer_revenue_deduction_commission_check CHECK ((deduction_commission >= (0)::numeric)),
    CONSTRAINT farmer_revenue_deduction_grading_check CHECK ((deduction_grading >= (0)::numeric)),
    CONSTRAINT farmer_revenue_deduction_other_check CHECK ((deduction_other >= (0)::numeric)),
    CONSTRAINT farmer_revenue_deduction_transport_check CHECK ((deduction_transport >= (0)::numeric)),
    CONSTRAINT farmer_revenue_gross_amount_check CHECK ((gross_amount >= (0)::numeric)),
    CONSTRAINT farmer_revenue_payment_status_check CHECK (((payment_status)::text = ANY ((ARRAY['pending'::character varying, 'partial'::character varying, 'received'::character varying, 'disputed'::character varying, 'written_off'::character varying])::text[]))),
    CONSTRAINT farmer_revenue_quantity_kg_check CHECK (((quantity_kg IS NULL) OR (quantity_kg > (0)::numeric))),
    CONSTRAINT farmer_revenue_revenue_source_check CHECK (((revenue_source)::text = ANY ((ARRAY['crop'::character varying, 'dairy'::character varying, 'livestock'::character varying, 'fisheries'::character varying, 'processing'::character varying, 'compost'::character varying, 'custom_hiring'::character varying, 'equipment_rental'::character varying, 'solar'::character varying, 'carbon_credit'::character varying, 'export'::character varying, 'contract_farming'::character varying, 'subsidy'::character varying, 'other'::character varying])::text[])))
);


