-- Name: farmer_value_index; Type: TABLE; Schema: public; Owner: ebdesign_user
--

CREATE TABLE public.farmer_value_index (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    farmer_id uuid NOT NULL,
    season character varying(30) NOT NULL,
    year smallint NOT NULL,
    total_cost numeric(20,4) DEFAULT 0,
    total_revenue numeric(20,4) DEFAULT 0,
    net_margin numeric(20,4) GENERATED ALWAYS AS ((COALESCE(total_revenue, (0)::numeric) - COALESCE(total_cost, (0)::numeric))) STORED,
    margin_pct numeric(8,4) GENERATED ALWAYS AS (
CASE
    WHEN (total_revenue > (0)::numeric) THEN (((total_revenue - COALESCE(total_cost, (0)::numeric)) / total_revenue) * (100)::numeric)
    ELSE NULL::numeric
END) STORED,
    potential_savings numeric(20,4) DEFAULT 0,
    unclaimed_subsidy numeric(20,4) DEFAULT 0,
    foregone_revenue numeric(20,4) DEFAULT 0,
    fvi_score numeric(6,2),
    data_confidence numeric(5,2) NOT NULL,
    inputs_breakdown jsonb NOT NULL,
    computed_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT farmer_value_index_data_confidence_check CHECK (((data_confidence >= (0)::numeric) AND (data_confidence <= (100)::numeric))),
    CONSTRAINT farmer_value_index_fvi_score_check CHECK (((fvi_score IS NULL) OR ((fvi_score >= (0)::numeric) AND (fvi_score <= (100)::numeric))))
);


