    CONSTRAINT fixed_assets_depreciation_method_check CHECK (((depreciation_method)::text = ANY ((ARRAY['straight_line'::character varying, 'declining_balance'::character varying, 'units_of_production'::character varying, 'wdv'::character varying])::text[]))),
    CONSTRAINT fixed_assets_salvage_value_check CHECK ((salvage_value >= (0)::numeric)),
    CONSTRAINT fixed_assets_status_check CHECK (((status)::text = ANY ((ARRAY['active'::character varying, 'under_maintenance'::character varying, 'disposed'::character varying, 'written_off'::character varying, 'transferred'::character varying])::text[]))),
    CONSTRAINT fixed_assets_useful_life_months_check CHECK ((useful_life_months > 0))
);


