--
-- Name: folu_land_parcels; Type: TABLE; Schema: public; Owner: ebdesign_user
--

CREATE TABLE public.folu_land_parcels (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    parcel_code character varying(50) NOT NULL,
    farmer_id uuid,
    area_ha numeric(12,4) NOT NULL,
    land_use_class character varying(40) NOT NULL,
    previous_land_use character varying(40),
    is_jhum boolean DEFAULT false,
    jhum_cycle_years smallint,
    state character varying(60),
    district character varying(60),
    village character varying(120),
    latitude numeric(10,7),
    longitude numeric(11,7),
    surveyed_on date,
    survey_method character varying(30),
    created_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT folu_land_parcels_area_ha_check CHECK ((area_ha > (0)::numeric)),
    CONSTRAINT folu_land_parcels_jhum_cycle_years_check CHECK (((jhum_cycle_years IS NULL) OR (jhum_cycle_years > 0))),
    CONSTRAINT folu_land_parcels_land_use_class_check CHECK (((land_use_class)::text = ANY ((ARRAY['cropland'::character varying, 'forest'::character varying, 'agroforestry'::character varying, 'grassland'::character varying, 'wetland'::character varying, 'settlement'::character varying, 'fallow'::character varying, 'plantation'::character varying, 'shifting_cultivation'::character varying])::text[]))),
    CONSTRAINT folu_land_parcels_latitude_check CHECK (((latitude IS NULL) OR ((latitude >= ('-90'::integer)::numeric) AND (latitude <= (90)::numeric)))),
    CONSTRAINT folu_land_parcels_longitude_check CHECK (((longitude IS NULL) OR ((longitude >= ('-180'::integer)::numeric) AND (longitude <= (180)::numeric)))),
    CONSTRAINT folu_land_parcels_survey_method_check CHECK (((survey_method IS NULL) OR ((survey_method)::text = ANY ((ARRAY['gps'::character varying, 'satellite'::character varying, 'drone'::character varying, 'declared'::character varying, 'revenue_record'::character varying])::text[]))))
);


ALTER TABLE public.folu_land_parcels OWNER TO ebdesign_user;

