--

CREATE TABLE public.folu_land_use_change (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    parcel_id uuid NOT NULL,
    from_class character varying(40) NOT NULL,
    to_class character varying(40) NOT NULL,
    area_changed_ha numeric(12,4) NOT NULL,
    change_date date NOT NULL,
    is_deforestation boolean GENERATED ALWAYS AS ((((from_class)::text = 'forest'::text) AND ((to_class)::text <> 'forest'::text))) STORED,
    driver character varying(60),
    evidence_source character varying(30),
    verified boolean DEFAULT false,
    verified_by uuid,
    created_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT change_is_a_change CHECK (((from_class)::text <> (to_class)::text)),
    CONSTRAINT folu_land_use_change_area_changed_ha_check CHECK ((area_changed_ha > (0)::numeric)),
    CONSTRAINT folu_land_use_change_evidence_source_check CHECK (((evidence_source IS NULL) OR ((evidence_source)::text = ANY ((ARRAY['satellite'::character varying, 'drone'::character varying, 'field_survey'::character varying, 'declared'::character varying])::text[]))))
);


