--
-- Name: gst_compliance_status; Type: VIEW; Schema: public; Owner: ebdesign_user
--

CREATE VIEW public.gst_compliance_status AS
 SELECT gcr.entity_id,
    gcr.entity_type,
    gcr.gst_number,
    gcr.compliance_type,
    gcr.compliance_status,
    gcr.compliance_score,
    gcr.compliance_date,
    gcr.next_compliance_date,
        CASE
            WHEN (gcr.next_compliance_date < CURRENT_DATE) THEN 'overdue'::text
            WHEN (gcr.next_compliance_date <= (CURRENT_DATE + '7 days'::interval)) THEN 'due_soon'::text
            ELSE 'on_track'::text
        END AS urgency_status
   FROM public.gst_compliance_records gcr
  WHERE (gcr.compliance_date = ( SELECT max(gcr2.compliance_date) AS max
           FROM public.gst_compliance_records gcr2
          WHERE ((gcr2.entity_id = gcr.entity_id) AND ((gcr2.entity_type)::text = (gcr.entity_type)::text) AND ((gcr2.compliance_type)::text = (gcr.compliance_type)::text))));


ALTER TABLE public.gst_compliance_status OWNER TO ebdesign_user;

