--
-- Name: gst_monthly_summary; Type: VIEW; Schema: public; Owner: ebdesign_user
--

CREATE VIEW public.gst_monthly_summary AS
 SELECT date_trunc('month'::text, (gi.invoice_date)::timestamp with time zone) AS month,
    count(DISTINCT gi.id) AS total_invoices,
    sum(gi.total_amount) AS total_taxable_value,
    sum(gi.total_gst) AS total_gst_collected,
    sum(gi.cgst_amount) AS total_cgst,
    sum(gi.sgst_amount) AS total_sgst,
    sum(gi.igst_amount) AS total_igst,
    count(DISTINCT gi.customer_gst_number) AS unique_customers
   FROM public.gst_invoices gi
  WHERE ((gi.invoice_status)::text = 'generated'::text)
  GROUP BY (date_trunc('month'::text, (gi.invoice_date)::timestamp with time zone))
  ORDER BY (date_trunc('month'::text, (gi.invoice_date)::timestamp with time zone)) DESC;


ALTER TABLE public.gst_monthly_summary OWNER TO ebdesign_user;

