--
-- Name: gst_pending_payments; Type: VIEW; Schema: public; Owner: ebdesign_user
--

CREATE VIEW public.gst_pending_payments AS
 SELECT gp.id,
    gp.return_id,
    gp.payment_type,
    gp.tax_type,
    gp.amount,
    gp.payment_date,
    gp.payment_method,
    gp.transaction_id,
    gp.bank_name,
    gp.branch_name,
    gp.challan_number,
    gp.payment_status,
    gp.created_by,
    gp.created_at,
    gp.updated_at,
    gr.return_period,
    gr.taxpayer_gst_number,
    gr.taxpayer_name
   FROM (public.gst_payments gp
     LEFT JOIN public.gst_returns gr ON ((gp.return_id = gr.id)))
  WHERE ((gp.payment_status)::text = 'pending'::text)
  ORDER BY gp.payment_date;


