--
-- Name: gstr_filings; Type: TABLE; Schema: public; Owner: ebdesign_user
--

CREATE TABLE public.gstr_filings (
    id bigint NOT NULL,
    return_type character varying(12) NOT NULL,
    period character varying(7) NOT NULL,
    gstin character varying(15) NOT NULL,
    b2b_taxable_inr numeric(16,2) DEFAULT 0 NOT NULL,
    b2c_taxable_inr numeric(16,2) DEFAULT 0 NOT NULL,
    total_cgst_inr numeric(16,2) DEFAULT 0 NOT NULL,
    total_sgst_inr numeric(16,2) DEFAULT 0 NOT NULL,
    total_igst_inr numeric(16,2) DEFAULT 0 NOT NULL,
    itc_claimed_inr numeric(16,2) DEFAULT 0 NOT NULL,
    generated_json jsonb,
    status character varying(20) DEFAULT 'draft'::character varying NOT NULL,
    filed_on date,
    arn character varying(40),
    created_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT filed_return_has_arn CHECK ((((status)::text <> 'filed'::text) OR (arn IS NOT NULL))),
    CONSTRAINT gstr_filings_return_type_check CHECK (((return_type)::text = ANY ((ARRAY['GSTR-1'::character varying, 'GSTR-3B'::character varying, 'GSTR-9'::character varying, 'CMP-08'::character varying])::text[]))),
    CONSTRAINT gstr_filings_status_check CHECK (((status)::text = ANY ((ARRAY['draft'::character varying, 'generated'::character varying, 'filed'::character varying, 'revised'::character varying, 'error'::character varying])::text[])))
);


