    rate_branded_packaged numeric(4,2)
);


ALTER TABLE public.hsn_gst_mapping OWNER TO ebdesign_user;

--
-- Name: COLUMN hsn_gst_mapping.branding_dependent; Type: COMMENT; Schema: public; Owner: ebdesign_user
--

COMMENT ON COLUMN public.hsn_gst_mapping.branding_dependent IS 'TRUE only for the specific staple HSN codes where CBIC''s branded/unbranded test actually changes the rate (per the branded-goods carve-out in the goods exemption/rate notification structure for agricultural staples). FALSE (default) for every other HSN code, which keeps one fixed gst_rate regardless of packaging or brand.';


--
-- Name: COLUMN hsn_gst_mapping.rate_loose_unbranded; Type: COMMENT; Schema: public; Owner: ebdesign_user
--

COMMENT ON COLUMN public.hsn_gst_mapping.rate_loose_unbranded IS 'Rate when sold loose or otherwise NOT put up in a unit container bearing a registered brand name. Only meaningful when branding_dependent = TRUE.';


--
-- Name: COLUMN hsn_gst_mapping.rate_branded_packaged; Type: COMMENT; Schema: public; Owner: ebdesign_user
--

COMMENT ON COLUMN public.hsn_gst_mapping.rate_branded_packaged IS 'Rate when put up in a unit container AND bearing a registered brand name (both conditions, per the notification wording) — the operative test that moves these goods out of the NIL entry. Only meaningful when branding_dependent = TRUE.';


