-- Name: incentive_pool_cycles; Type: TABLE; Schema: public; Owner: ebdesign_user
--

CREATE TABLE public.incentive_pool_cycles (
    id integer NOT NULL,
    cycle_code character varying(40) NOT NULL,
    period_start date NOT NULL,
    period_end date NOT NULL,
    total_spread_collected_inr numeric(16,2) DEFAULT 0 NOT NULL,
    farmer_share_pct numeric(5,2) DEFAULT 40.00 NOT NULL,
    pool_amount_inr numeric(16,2) GENERATED ALWAYS AS (round(((total_spread_collected_inr * farmer_share_pct) / (100)::numeric), 2)) STORED,
    eligible_farmer_count integer DEFAULT 0 NOT NULL,
    status character varying(20) DEFAULT 'accumulating'::character varying NOT NULL,
    distribution_date date,
    created_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT cycle_period_valid CHECK ((period_end >= period_start)),
    CONSTRAINT distributed_cycle_has_date CHECK ((((status)::text <> 'distributed'::text) OR (distribution_date IS NOT NULL))),
    CONSTRAINT incentive_pool_cycles_eligible_farmer_count_check CHECK ((eligible_farmer_count >= 0)),
    CONSTRAINT incentive_pool_cycles_farmer_share_pct_check CHECK (((farmer_share_pct >= (0)::numeric) AND (farmer_share_pct <= (100)::numeric))),
    CONSTRAINT incentive_pool_cycles_status_check CHECK (((status)::text = ANY ((ARRAY['accumulating'::character varying, 'closed'::character varying, 'distributing'::character varying, 'distributed'::character varying])::text[]))),
    CONSTRAINT incentive_pool_cycles_total_spread_collected_inr_check CHECK ((total_spread_collected_inr >= (0)::numeric))
);


