    CONSTRAINT incentive_pool_redemptions_amount_inr_check CHECK ((amount_inr > (0)::numeric)),
    CONSTRAINT incentive_pool_redemptions_bonus_pct_check CHECK (((bonus_pct >= (0)::numeric) AND (bonus_pct <= (100)::numeric))),
    CONSTRAINT incentive_pool_redemptions_redemption_mode_check CHECK (((redemption_mode)::text = ANY ((ARRAY['cash_wallet'::character varying, 'equipment_credit'::character varying, 'input_credit'::character varying, 'reinvest'::character varying])::text[])))
);


