-- Name: mandi_prices; Type: TABLE; Schema: public; Owner: ebdesign_user
--

CREATE TABLE public.mandi_prices (
    id bigint NOT NULL,
    market_name character varying(160) NOT NULL,
    state character varying(60),
    district character varying(80),
    commodity character varying(120) NOT NULL,
    variety character varying(120),
    grade character varying(40),
    min_price_inr_per_qtl numeric(12,2),
    modal_price_inr_per_qtl numeric(12,2),
    max_price_inr_per_qtl numeric(12,2),
    arrivals_tonnes numeric(12,2),
    price_date date NOT NULL,
    source character varying(20) DEFAULT 'agmarknet'::character varying NOT NULL,
    fetched_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT mandi_price_band_ordered CHECK (((min_price_inr_per_qtl IS NULL) OR (max_price_inr_per_qtl IS NULL) OR (min_price_inr_per_qtl <= max_price_inr_per_qtl))),
    CONSTRAINT mandi_prices_max_price_inr_per_qtl_check CHECK (((max_price_inr_per_qtl IS NULL) OR (max_price_inr_per_qtl >= (0)::numeric))),
    CONSTRAINT mandi_prices_min_price_inr_per_qtl_check CHECK (((min_price_inr_per_qtl IS NULL) OR (min_price_inr_per_qtl >= (0)::numeric))),
    CONSTRAINT mandi_prices_modal_price_inr_per_qtl_check CHECK (((modal_price_inr_per_qtl IS NULL) OR (modal_price_inr_per_qtl >= (0)::numeric))),
    CONSTRAINT mandi_prices_source_check CHECK (((source)::text = ANY ((ARRAY['agmarknet'::character varying, 'enam'::character varying, 'apmc_manual'::character varying, 'trader_report'::character varying, 'estimated'::character varying])::text[]))),
    CONSTRAINT modal_inside_band CHECK (((modal_price_inr_per_qtl IS NULL) OR (min_price_inr_per_qtl IS NULL) OR (max_price_inr_per_qtl IS NULL) OR ((modal_price_inr_per_qtl >= min_price_inr_per_qtl) AND (modal_price_inr_per_qtl <= max_price_inr_per_qtl))))
);


