--

CREATE TABLE public.packaging_shelf_life (
    id integer NOT NULL,
    product character varying(120) NOT NULL,
    packaging_method character varying(60) DEFAULT 'vacuum_n2_map'::character varying NOT NULL,
    conventional_months_min numeric(6,2),
    conventional_months_max numeric(6,2),
    improved_months_min numeric(6,2),
    improved_months_max numeric(6,2),
    removes_cold_chain boolean DEFAULT false NOT NULL,
    cost_change_inr_per_pack numeric(10,2),
    business_impact text NOT NULL,
    data_provenance character varying(20) DEFAULT 'assumed'::character varying NOT NULL,
    source_document character varying(120) DEFAULT 'NE_Harvest_Complete_Business_Report.html'::character varying NOT NULL,
    CONSTRAINT improved_shelf_life_is_longer CHECK (((improved_months_min IS NULL) OR (conventional_months_min IS NULL) OR (improved_months_min >= conventional_months_min))),
    CONSTRAINT packaging_shelf_life_conventional_months_max_check CHECK (((conventional_months_max IS NULL) OR (conventional_months_max >= (0)::numeric))),
    CONSTRAINT packaging_shelf_life_conventional_months_min_check CHECK (((conventional_months_min IS NULL) OR (conventional_months_min >= (0)::numeric))),
    CONSTRAINT packaging_shelf_life_data_provenance_check CHECK (((data_provenance)::text = ANY ((ARRAY['real'::character varying, 'estimated'::character varying, 'assumed'::character varying])::text[]))),
    CONSTRAINT packaging_shelf_life_improved_months_max_check CHECK (((improved_months_max IS NULL) OR (improved_months_max >= (0)::numeric))),
    CONSTRAINT packaging_shelf_life_improved_months_min_check CHECK (((improved_months_min IS NULL) OR (improved_months_min >= (0)::numeric))),
    CONSTRAINT packaging_shelf_life_packaging_method_check CHECK (((packaging_method)::text = ANY ((ARRAY['conventional'::character varying, 'vacuum_n2_map'::character varying, 'ema'::character varying, 'cold_chain_only'::character varying, 'ambient'::character varying])::text[])))
);


