    chemical_action text,
    organic_safe boolean DEFAULT true NOT NULL,
    banned_for_export_markets text[],
    CONSTRAINT non_chemical_option_given CHECK ((length(TRIM(BOTH FROM non_chemical_action)) > 0)),
    CONSTRAINT organic_safe_has_no_export_ban CHECK (((organic_safe = false) OR (banned_for_export_markets IS NULL))),
    CONSTRAINT pest_disease_forecasts_confidence_pct_check CHECK (((confidence_pct >= (0)::numeric) AND (confidence_pct <= (100)::numeric))),
    CONSTRAINT pest_disease_forecasts_kind_check CHECK (((kind)::text = ANY ((ARRAY['pest'::character varying, 'disease'::character varying])::text[]))),
    CONSTRAINT pest_disease_forecasts_risk_level_check CHECK (((risk_level)::text = ANY ((ARRAY['low'::character varying, 'moderate'::character varying, 'high'::character varying, 'severe'::character varying])::text[])))
);


