--
-- Name: prediction_accuracy_summary; Type: VIEW; Schema: public; Owner: ebdesign_user
--

CREATE VIEW public.prediction_accuracy_summary AS
 SELECT pm.model_name,
    pm.model_type,
    p.prediction_type,
    count(*) AS total_predictions,
    avg(p.prediction_accuracy) AS avg_accuracy,
    stddev(p.prediction_accuracy) AS accuracy_stddev,
    min(p.prediction_accuracy) AS min_accuracy,
    max(p.prediction_accuracy) AS max_accuracy
   FROM (public.predictions p
     JOIN public.predictive_models pm ON ((p.model_id = pm.id)))
  WHERE (p.actual_value IS NOT NULL)
  GROUP BY pm.model_name, pm.model_type, p.prediction_type;


ALTER TABLE public.prediction_accuracy_summary OWNER TO ebdesign_user;

