    effective_price numeric,
    discount_percentage numeric,
    discount_type character varying(50),
    source_location jsonb,
    valid_from date,
    valid_to date,
    created_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP,
    updated_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP,
    pack_size_g numeric(10,2),
    unit character varying(20) DEFAULT 'kg'::character varying,
    price_per_kg_inr numeric(12,2),
    match_confidence numeric(4,3),
    collection_method character varying(30),
    source_url text,
    terms_reviewed boolean DEFAULT false,
    collection_note text,
    observed_by uuid,
    is_organic boolean,
    is_gi_tagged boolean,
    in_stock boolean
);


ALTER TABLE public.price_intelligence OWNER TO ebdesign_user;

--
-- Name: COLUMN price_intelligence.price_per_kg_inr; Type: COMMENT; Schema: public; Owner: ebdesign_user
--

COMMENT ON COLUMN public.price_intelligence.price_per_kg_inr IS 'Normalised per-kg price. Set by the service from effective_price and pack_size_g. Not a generated column because 042 rows already carry prices with no pack size recorded, and a generated column would make those NULL permanently with no way to backfill.';


--
-- Name: COLUMN price_intelligence.collection_method; Type: COMMENT; Schema: public; Owner: ebdesign_user
--

COMMENT ON COLUMN public.price_intelligence.collection_method IS 'One of: public_api, licensed_feed, partner_share, manual_observation, published_price_list, automated_collection. Enforced in the service layer rather than by CHECK, because rows predating migration 059 have NULL here and a CHECK would reject them on any UPDATE.';


--
-- Name: price_windows; Type: TABLE; Schema: public; Owner: ebdesign_user
--

CREATE TABLE public.price_windows (
    id bigint NOT NULL,
    product_id character varying(80) NOT NULL,
    window_start timestamp without time zone NOT NULL,
    window_seconds integer DEFAULT 300 NOT NULL,
    window_end timestamp without time zone GENERATED ALWAYS AS ((window_start + make_interval(secs => (window_seconds)::double precision))) STORED,
    base_price_inr numeric(12,2) NOT NULL,
    live_price_inr numeric(12,2) NOT NULL,
    band_pct numeric(5,2) DEFAULT 8.00 NOT NULL,
    source character varying(20) DEFAULT 'synthetic'::character varying NOT NULL,
    source_ref character varying(120),
    created_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT price_windows_band_pct_check CHECK (((band_pct >= (0)::numeric) AND (band_pct <= (100)::numeric))),
    CONSTRAINT price_windows_base_price_inr_check CHECK ((base_price_inr > (0)::numeric)),
    CONSTRAINT price_windows_live_price_inr_check CHECK ((live_price_inr > (0)::numeric)),
    CONSTRAINT price_windows_source_check CHECK (((source)::text = ANY ((ARRAY['synthetic'::character varying, 'agmarknet'::character varying, 'enam'::character varying, 'mandi_manual'::character varying, 'platform_actual'::character varying])::text[]))),
    CONSTRAINT price_windows_window_seconds_check CHECK ((window_seconds > 0)),
    CONSTRAINT real_price_names_its_source CHECK ((((source)::text = 'synthetic'::text) OR (source_ref IS NOT NULL))),
    CONSTRAINT synthetic_price_within_band CHECK ((((source)::text <> 'synthetic'::text) OR ((live_price_inr >= (base_price_inr * ((1)::numeric - (band_pct / (100)::numeric)))) AND (live_price_inr <= (base_price_inr * ((1)::numeric + (band_pct / (100)::numeric)))))))
);


