    description text,
    usp text,
    gi_status boolean DEFAULT false,
    gi_certificate_number character varying(100),
    gi_registry_date date,
    organic boolean DEFAULT false,
    organic_certificate_number character varying(100),
    nutrition_data jsonb DEFAULT '{}'::jsonb,
    images jsonb DEFAULT '[]'::jsonb,
    base_price numeric(10,2) NOT NULL,
    map_price numeric(10,2),
    retail_price numeric(10,2),
    weight_per_unit numeric(10,3),
    dimensions jsonb,
    tags text[],
    meta_title character varying(255),
    meta_description text,
    is_active boolean DEFAULT true,
    featured boolean DEFAULT false,
    created_by uuid,
    created_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP,
    updated_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP,
    gst_applicable boolean DEFAULT true,
    gst_rate numeric(5,2),
    hsn_code character varying(20),
    is_branded_packaged boolean DEFAULT false NOT NULL,
    registered_brand_name character varying(255),
    unit_container_size character varying(50),
    image_generation_status character varying(20) DEFAULT 'not_requested'::character varying,
    image_generated_at timestamp without time zone,
    video_generation_status character varying(20) DEFAULT 'not_requested'::character varying,
    video_url text,
    video_script jsonb,
    video_generated_at timestamp without time zone,
    variety_directory_id integer,
    search_vector tsvector,
    CONSTRAINT products_image_generation_status_check CHECK (((image_generation_status)::text = ANY ((ARRAY['not_requested'::character varying, 'pending'::character varying, 'not_configured'::character varying, 'completed'::character varying, 'failed'::character varying])::text[]))),
    CONSTRAINT products_video_generation_status_check CHECK (((video_generation_status)::text = ANY ((ARRAY['not_requested'::character varying, 'pending'::character varying, 'not_configured'::character varying, 'completed'::character varying, 'failed'::character varying])::text[])))
);


