-- Name: states; Type: TABLE; Schema: public; Owner: ebdesign_user
--

CREATE TABLE public.states (
    id integer NOT NULL,
    name character varying(100) NOT NULL,
    code character varying(10) NOT NULL,
    region character varying(50),
    is_active boolean DEFAULT true,
    created_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP
);


ALTER TABLE public.states OWNER TO ebdesign_user;

--
-- Name: product_performance; Type: VIEW; Schema: public; Owner: ebdesign_user
--

CREATE VIEW public.product_performance AS
 SELECT p.id,
    p.name,
    p.category_id,
    c.name AS category_name,
    p.state_id,
    s.name AS state_name,
    count(DISTINCT oi.order_id) AS order_count,
    COALESCE(sum(oi.quantity), (0)::bigint) AS total_quantity_sold,
    COALESCE(sum(oi.total_price), (0)::numeric) AS total_revenue,
    COALESCE(avg(oi.unit_price), (0)::numeric) AS average_price,
    p.gi_status,
    p.is_active
   FROM (((public.products p
     LEFT JOIN public.categories c ON ((p.category_id = c.id)))
     LEFT JOIN public.states s ON ((p.state_id = s.id)))
     LEFT JOIN public.order_items oi ON ((p.id = oi.product_id)))
  GROUP BY p.id, p.name, p.category_id, c.name, p.state_id, s.name, p.gi_status, p.is_active;


