    CONSTRAINT lost_quote_states_why CHECK ((((outcome)::text <> 'lost'::text) OR (loss_reason IS NOT NULL))),
    CONSTRAINT quote_outcomes_loss_reason_check CHECK (((loss_reason IS NULL) OR ((loss_reason)::text = ANY ((ARRAY['price'::character varying, 'delivery_time'::character varying, 'quality_doubt'::character varying, 'payment_terms'::character varying, 'competitor'::character varying, 'no_response'::character varying, 'quantity_mismatch'::character varying, 'certification_missing'::character varying, 'other'::character varying])::text[])))),
    CONSTRAINT quote_outcomes_outcome_check CHECK (((outcome)::text = ANY ((ARRAY['pending'::character varying, 'won'::character varying, 'lost'::character varying, 'expired'::character varying, 'withdrawn'::character varying])::text[]))),
    CONSTRAINT quote_outcomes_quoted_price_inr_per_kg_check CHECK (((quoted_price_inr_per_kg IS NULL) OR (quoted_price_inr_per_kg > (0)::numeric)))
);


