--
-- Name: reu_cultivation_summary; Type: VIEW; Schema: public; Owner: ebdesign_user
--

CREATE VIEW public.reu_cultivation_summary AS
 SELECT reu.id,
    reu.reu_number,
    reu.reu_type,
    count(fc.id) AS input_purchases,
    sum(fc.total_cost) AS total_input_cost,
    sum(fc.subsidy_amount) AS total_subsidy_received,
    count(*) FILTER (WHERE fc.financing_required) AS financed_inputs,
    fc.season,
    fc.year
   FROM (public.rural_economic_units reu
     LEFT JOIN public.farm_consumables fc ON ((fc.reu_id = reu.id)))
  WHERE ((reu.status)::text = 'active'::text)
  GROUP BY reu.id, reu.reu_number, reu.reu_type, fc.season, fc.year;


