--
-- Name: reu_dashboard_summary; Type: MATERIALIZED VIEW; Schema: public; Owner: ebdesign_user
--

CREATE MATERIALIZED VIEW public.reu_dashboard_summary AS
 SELECT reu.id,
    reu.reu_number,
    reu.reu_type,
    reu.location,
    COALESCE(household_economy.total_savings, (0)::numeric) AS household_savings,
    COALESCE(household_economy.total_orders, 0) AS household_orders,
    COALESCE(sum(farm_consumables.total_cost), (0)::numeric) AS farm_consumables_cost,
    COALESCE(count(DISTINCT farm_consumables.id), (0)::bigint) AS farm_consumables_count,
    COALESCE(sum(machinery_access.total_cost), (0)::numeric) AS machinery_cost,
    COALESCE(count(DISTINCT machinery_access.id), (0)::bigint) AS machinery_bookings,
    COALESCE(sum(shared_infrastructure_access.total_cost), (0)::numeric) AS infrastructure_cost,
    COALESCE(count(DISTINCT shared_infrastructure_access.id), (0)::bigint) AS infrastructure_bookings,
    COALESCE(count(DISTINCT rural_enterprises.id), (0)::bigint) AS active_enterprises,
    COALESCE(sum(rural_enterprises.annual_revenue), (0)::numeric) AS enterprise_revenue,
    COALESCE(sum(renewable_energy_systems.capacity_kw), (0)::numeric) AS total_energy_capacity,
    COALESCE(sum(renewable_energy_systems.annual_savings), (0)::numeric) AS annual_energy_savings,
    COALESCE(sum(rural_finance.loan_amount), (0)::numeric) AS total_loans,
    COALESCE(sum(rural_finance.outstanding_principal), (0)::numeric) AS outstanding_loans,
    COALESCE(count(DISTINCT ai_advisories.id), (0)::bigint) AS total_advisories,
    COALESCE(count(DISTINCT
        CASE
            WHEN ai_advisories.follow_up_required THEN ai_advisories.id
            ELSE NULL::uuid
        END), (0)::bigint) AS pending_followups,
    COALESCE(sum(market_access.total_value), (0)::numeric) AS total_sales,
    COALESCE(count(DISTINCT market_access.id), (0)::bigint) AS total_sales_count
   FROM (((((((((public.rural_economic_units reu
     LEFT JOIN public.household_economy ON ((household_economy.reu_id = reu.id)))
     LEFT JOIN public.farm_consumables ON ((farm_consumables.reu_id = reu.id)))
     LEFT JOIN public.machinery_access ON ((machinery_access.reu_id = reu.id)))
     LEFT JOIN public.shared_infrastructure_access ON ((shared_infrastructure_access.reu_id = reu.id)))
     LEFT JOIN public.rural_enterprises ON (((rural_enterprises.reu_id = reu.id) AND ((rural_enterprises.status)::text = 'operational'::text))))
     LEFT JOIN public.renewable_energy_systems ON (((renewable_energy_systems.reu_id = reu.id) AND ((renewable_energy_systems.status)::text = 'operational'::text))))
     LEFT JOIN public.rural_finance ON (((rural_finance.reu_id = reu.id) AND ((rural_finance.status)::text = 'active'::text))))
     LEFT JOIN public.ai_advisories ON ((ai_advisories.reu_id = reu.id)))
     LEFT JOIN public.market_access ON (((market_access.reu_id = reu.id) AND ((market_access.status)::text = 'delivered'::text))))
  WHERE ((reu.status)::text = 'active'::text)
  GROUP BY reu.id, reu.reu_number, reu.reu_type, reu.location, household_economy.total_savings, household_economy.total_orders
  WITH NO DATA;


ALTER TABLE public.reu_dashboard_summary OWNER TO ebdesign_user;

--
-- Name: reu_enterprise_summary; Type: VIEW; Schema: public; Owner: ebdesign_user
--

CREATE VIEW public.reu_enterprise_summary AS
 SELECT reu.id,
    reu.reu_number,
    reu.reu_type,
    count(DISTINCT ent.id) AS total_enterprises,
    count(DISTINCT
        CASE
            WHEN ((ent.status)::text = 'operational'::text) THEN ent.id
            ELSE NULL::uuid
        END) AS operational_enterprises,
    sum(ent.total_investment) AS total_enterprise_investment,
    sum(ent.annual_revenue) AS total_enterprise_revenue,
    sum(ent.annual_profit) AS total_enterprise_profit
   FROM (public.rural_economic_units reu
     LEFT JOIN public.rural_enterprises ent ON ((ent.reu_id = reu.id)))
  WHERE ((reu.status)::text = 'active'::text)
  GROUP BY reu.id, reu.reu_number, reu.reu_type;


ALTER TABLE public.reu_enterprise_summary OWNER TO ebdesign_user;

--
-- Name: reu_financial_summary; Type: VIEW; Schema: public; Owner: ebdesign_user
--

CREATE VIEW public.reu_financial_summary AS
 SELECT reu.id,
    reu.reu_number,
    reu.reu_type,
    count(DISTINCT rf.id) AS total_loans,
    sum(rf.loan_amount) AS total_loan_amount,
    sum(rf.outstanding_principal) AS total_outstanding_principal,
    avg(rf.interest_rate) AS average_interest_rate,
    count(DISTINCT
        CASE
            WHEN ((rf.status)::text = 'active'::text) THEN rf.id
            ELSE NULL::uuid
        END) AS active_loans,
    count(DISTINCT
        CASE
            WHEN rf.subsidy_linked THEN rf.id
            ELSE NULL::uuid
        END) AS subsidy_linked_loans
   FROM (public.rural_economic_units reu
     LEFT JOIN public.rural_finance rf ON ((rf.reu_id = reu.id)))
  WHERE ((reu.status)::text = 'active'::text)
  GROUP BY reu.id, reu.reu_number, reu.reu_type;


ALTER TABLE public.reu_financial_summary OWNER TO ebdesign_user;

--
-- Name: reu_household_economy_summary; Type: VIEW; Schema: public; Owner: ebdesign_user
--

CREATE VIEW public.reu_household_economy_summary AS
 SELECT reu.id,
    reu.reu_number,
    reu.reu_type,
    he.monthly_budget,
    he.annual_budget,
    he.subscription_status,
    he.consumption_savings,
    he.total_orders,
    he.total_spent,
    he.created_at AS subscription_start_date
   FROM (public.rural_economic_units reu
     LEFT JOIN public.household_economy he ON ((he.reu_id = reu.id)))
  WHERE ((reu.status)::text = 'active'::text);


