--
-- Name: risk_register; Type: TABLE; Schema: public; Owner: ebdesign_user
--

CREATE TABLE public.risk_register (
    id integer NOT NULL,
    risk_code character varying(40) NOT NULL,
    title character varying(255) NOT NULL,
    category character varying(40) NOT NULL,
    description text NOT NULL,
    inherent_likelihood smallint,
    inherent_impact smallint,
    inherent_score smallint GENERATED ALWAYS AS ((COALESCE((inherent_likelihood)::integer, 0) * COALESCE((inherent_impact)::integer, 0))) STORED,
    residual_likelihood smallint,
    residual_impact smallint,
    residual_score smallint GENERATED ALWAYS AS ((COALESCE((residual_likelihood)::integer, 0) * COALESCE((residual_impact)::integer, 0))) STORED,
    treatment character varying(20) DEFAULT 'mitigate'::character varying NOT NULL,
    accepted_by uuid,
    owner_role character varying(60),
    review_frequency character varying(20) DEFAULT 'quarterly'::character varying,
    last_reviewed date,
    next_review date,
    status character varying(20) DEFAULT 'open'::character varying NOT NULL,
    created_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT risk_acceptance_needs_owner CHECK ((((treatment)::text <> 'accept'::text) OR (accepted_by IS NOT NULL))),
    CONSTRAINT risk_register_category_check CHECK (((category)::text = ANY ((ARRAY['operational'::character varying, 'financial'::character varying, 'compliance'::character varying, 'reputational'::character varying, 'strategic'::character varying, 'climate'::character varying, 'supply_chain'::character varying, 'cyber'::character varying, 'legal'::character varying])::text[]))),
    CONSTRAINT risk_register_inherent_impact_check CHECK (((inherent_impact >= 1) AND (inherent_impact <= 5))),
    CONSTRAINT risk_register_inherent_likelihood_check CHECK (((inherent_likelihood >= 1) AND (inherent_likelihood <= 5))),
    CONSTRAINT risk_register_residual_impact_check CHECK (((residual_impact >= 1) AND (residual_impact <= 5))),
    CONSTRAINT risk_register_residual_likelihood_check CHECK (((residual_likelihood >= 1) AND (residual_likelihood <= 5))),
    CONSTRAINT risk_register_review_frequency_check CHECK (((review_frequency)::text = ANY ((ARRAY['monthly'::character varying, 'quarterly'::character varying, 'annual'::character varying])::text[]))),
    CONSTRAINT risk_register_status_check CHECK (((status)::text = ANY ((ARRAY['open'::character varying, 'monitored'::character varying, 'closed'::character varying, 'escalated'::character varying, 'materialised'::character varying])::text[]))),
    CONSTRAINT risk_register_treatment_check CHECK (((treatment)::text = ANY ((ARRAY['accept'::character varying, 'mitigate'::character varying, 'transfer'::character varying, 'avoid'::character varying])::text[])))
);


