COMMENT ON TABLE public.temperature_readings IS 'Stores temperature and humidity readings';


--
-- Name: shipment_temperature_summary; Type: VIEW; Schema: public; Owner: ebdesign_user
--

CREATE VIEW public.shipment_temperature_summary AS
 SELECT temperature_readings.shipment_id,
    count(*) AS reading_count,
    avg(temperature_readings.temperature) AS avg_temperature,
    min(temperature_readings.temperature) AS min_temperature,
    max(temperature_readings.temperature) AS max_temperature,
    avg(temperature_readings.humidity) AS avg_humidity,
    min(temperature_readings."timestamp") AS first_reading,
    max(temperature_readings."timestamp") AS last_reading
   FROM public.temperature_readings
  GROUP BY temperature_readings.shipment_id;


ALTER TABLE public.shipment_temperature_summary OWNER TO ebdesign_user;

