--
-- Name: sponsored_listings; Type: TABLE; Schema: public; Owner: ebdesign_user
--

CREATE TABLE public.sponsored_listings (
    id bigint NOT NULL,
    product_id character varying(80) NOT NULL,
    sponsor_id uuid,
    sponsor_name character varying(160),
    category character varying(80) NOT NULL,
    bid_inr_per_click numeric(10,2),
    daily_budget_inr numeric(12,2),
    slot_position integer,
    starts_on date DEFAULT CURRENT_DATE NOT NULL,
    ends_on date,
    status character varying(20) DEFAULT 'active'::character varying NOT NULL,
    impressions bigint DEFAULT 0 NOT NULL,
    clicks bigint DEFAULT 0 NOT NULL,
    spend_inr numeric(14,2) DEFAULT 0 NOT NULL,
    disclosure_label character varying(40) DEFAULT 'Sponsored'::character varying NOT NULL,
    CONSTRAINT clicks_not_exceeding_impressions CHECK ((clicks <= impressions)),
    CONSTRAINT disclosure_not_blank CHECK ((length(TRIM(BOTH FROM disclosure_label)) > 0)),
    CONSTRAINT sponsored_dates_valid CHECK (((ends_on IS NULL) OR (ends_on >= starts_on))),
    CONSTRAINT sponsored_listings_bid_inr_per_click_check CHECK (((bid_inr_per_click IS NULL) OR (bid_inr_per_click >= (0)::numeric))),
    CONSTRAINT sponsored_listings_clicks_check CHECK ((clicks >= 0)),
    CONSTRAINT sponsored_listings_daily_budget_inr_check CHECK (((daily_budget_inr IS NULL) OR (daily_budget_inr >= (0)::numeric))),
    CONSTRAINT sponsored_listings_impressions_check CHECK ((impressions >= 0)),
    CONSTRAINT sponsored_listings_slot_position_check CHECK (((slot_position IS NULL) OR (slot_position > 0))),
    CONSTRAINT sponsored_listings_spend_inr_check CHECK ((spend_inr >= (0)::numeric)),
    CONSTRAINT sponsored_listings_status_check CHECK (((status)::text = ANY ((ARRAY['draft'::character varying, 'active'::character varying, 'paused'::character varying, 'exhausted'::character varying, 'ended'::character varying])::text[])))
);


