--
-- Name: staple_subscriptions; Type: TABLE; Schema: public; Owner: ebdesign_user
--

CREATE TABLE public.staple_subscriptions (
    id bigint NOT NULL,
    subscriber_id uuid,
    subscriber_type character varying(20) DEFAULT 'rwa'::character varying NOT NULL,
    subscriber_name character varying(200),
    product character varying(160) NOT NULL,
    quantity_kg numeric(12,2) NOT NULL,
    frequency_days integer DEFAULT 30 NOT NULL,
    locked_price_inr_per_kg numeric(12,2),
    price_lock_months integer,
    delivery_address text,
    next_delivery_on date,
    started_on date DEFAULT CURRENT_DATE NOT NULL,
    paused_until date,
    cancelled_on date,
    cancellation_reason text,
    status character varying(20) DEFAULT 'active'::character varying NOT NULL,
    created_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT cancelled_subscription_has_reason CHECK ((((status)::text <> 'cancelled'::text) OR (cancellation_reason IS NOT NULL))),
    CONSTRAINT price_lock_bounded CHECK (((price_lock_months IS NULL) OR (price_lock_months <= 12))),
    CONSTRAINT staple_subscriptions_frequency_days_check CHECK ((frequency_days > 0)),
    CONSTRAINT staple_subscriptions_locked_price_inr_per_kg_check CHECK (((locked_price_inr_per_kg IS NULL) OR (locked_price_inr_per_kg > (0)::numeric))),
    CONSTRAINT staple_subscriptions_price_lock_months_check CHECK (((price_lock_months IS NULL) OR (price_lock_months >= 0))),
    CONSTRAINT staple_subscriptions_quantity_kg_check CHECK ((quantity_kg > (0)::numeric)),
    CONSTRAINT staple_subscriptions_status_check CHECK (((status)::text = ANY ((ARRAY['active'::character varying, 'paused'::character varying, 'cancelled'::character varying, 'completed'::character varying, 'payment_failed'::character varying])::text[]))),
    CONSTRAINT staple_subscriptions_subscriber_type_check CHECK (((subscriber_type)::text = ANY ((ARRAY['rwa'::character varying, 'horeca'::character varying, 'institution'::character varying, 'household'::character varying, 'corporate'::character varying])::text[])))
);


ALTER TABLE public.staple_subscriptions OWNER TO ebdesign_user;

