--
-- Name: tds_deductions; Type: TABLE; Schema: public; Owner: ebdesign_user
--

CREATE TABLE public.tds_deductions (
    id bigint NOT NULL,
    deductee_id uuid,
    deductee_name character varying(200) NOT NULL,
    deductee_pan character varying(10),
    deductee_type character varying(30) NOT NULL,
    section character varying(20) NOT NULL,
    payment_amount_inr numeric(16,2) NOT NULL,
    tds_rate_pct numeric(5,2) NOT NULL,
    tds_amount_inr numeric(16,2) GENERATED ALWAYS AS (round(((payment_amount_inr * tds_rate_pct) / (100)::numeric), 2)) STORED,
    higher_rate_no_pan boolean DEFAULT false NOT NULL,
    quarter character varying(7) NOT NULL,
    financial_year character varying(9) NOT NULL,
    challan_no character varying(40),
    deposited_on date,
    form_26q_filed boolean DEFAULT false NOT NULL,
    created_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT filed_return_has_challan CHECK (((form_26q_filed = false) OR (challan_no IS NOT NULL))),
    CONSTRAINT no_pan_means_higher_rate CHECK (((deductee_pan IS NOT NULL) OR (higher_rate_no_pan = true))),
    CONSTRAINT tds_deductions_deductee_type_check CHECK (((deductee_type)::text = ANY ((ARRAY['transporter'::character varying, 'fpo'::character varying, 'vendor'::character varying, 'contractor'::character varying, 'professional'::character varying, 'commission_agent'::character varying])::text[]))),
    CONSTRAINT tds_deductions_payment_amount_inr_check CHECK ((payment_amount_inr > (0)::numeric)),
    CONSTRAINT tds_deductions_tds_rate_pct_check CHECK (((tds_rate_pct >= (0)::numeric) AND (tds_rate_pct <= (100)::numeric)))
);


ALTER TABLE public.tds_deductions OWNER TO ebdesign_user;

--
-- Name: tds_deductions_id_seq; Type: SEQUENCE; Schema: public; Owner: ebdesign_user
--

