    id integer NOT NULL,
    breakpoint_key character varying(30) NOT NULL,
    min_width_px integer NOT NULL,
    max_width_px integer,
    columns integer DEFAULT 12 NOT NULL,
    gutter_px integer DEFAULT 16 NOT NULL,
    typical_device character varying(60),
    notes text,
    CONSTRAINT breakpoint_range_valid CHECK (((max_width_px IS NULL) OR (max_width_px > min_width_px))),
    CONSTRAINT ui_breakpoints_columns_check CHECK ((columns > 0)),
    CONSTRAINT ui_breakpoints_gutter_px_check CHECK ((gutter_px >= 0)),
    CONSTRAINT ui_breakpoints_min_width_px_check CHECK ((min_width_px >= 0))
);


