    keyboard_operable boolean DEFAULT false NOT NULL,
    screen_reader_labelled boolean DEFAULT false NOT NULL,
    focus_visible boolean DEFAULT false NOT NULL,
    wcag_level character varying(4),
    states text[] DEFAULT '{}'::text[] NOT NULL,
    variants text[] DEFAULT '{}'::text[] NOT NULL,
    uses_tokens text[] DEFAULT '{}'::text[] NOT NULL,
    status character varying(20) DEFAULT 'draft'::character varying NOT NULL,
    replaced_by character varying(80),
    created_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT deprecated_component_has_successor CHECK ((((status)::text <> 'deprecated'::text) OR (replaced_by IS NOT NULL))),
    CONSTRAINT stable_component_is_accessible CHECK ((((status)::text <> 'stable'::text) OR ((keyboard_operable = true) AND (screen_reader_labelled = true) AND (focus_visible = true)))),
    CONSTRAINT ui_components_status_check CHECK (((status)::text = ANY ((ARRAY['draft'::character varying, 'review'::character varying, 'stable'::character varying, 'deprecated'::character varying])::text[]))),
    CONSTRAINT ui_components_wcag_level_check CHECK (((wcag_level IS NULL) OR ((wcag_level)::text = ANY ((ARRAY['A'::character varying, 'AA'::character varying, 'AAA'::character varying])::text[]))))
);


