    CONSTRAINT ui_feedback_rules_aria_live_check CHECK (((aria_live)::text = ANY ((ARRAY['off'::character varying, 'polite'::character varying, 'assertive'::character varying])::text[]))),
    CONSTRAINT ui_feedback_rules_channel_check CHECK (((channel)::text = ANY ((ARRAY['toast'::character varying, 'banner'::character varying, 'modal'::character varying, 'inline'::character varying, 'badge'::character varying, 'sound'::character varying, 'haptic'::character varying])::text[]))),
    CONSTRAINT ui_feedback_rules_severity_check CHECK (((severity)::text = ANY ((ARRAY['info'::character varying, 'success'::character varying, 'warning'::character varying, 'error'::character varying, 'critical'::character varying])::text[])))
);


