--
-- Name: v_a11y_summary; Type: VIEW; Schema: public; Owner: ebdesign_user
--

CREATE VIEW public.v_a11y_summary AS
 SELECT a11y_conformance.surface,
    a11y_conformance.surface_type,
    count(*) AS criteria_checked,
    count(*) FILTER (WHERE ((a11y_conformance.status)::text = 'pass'::text)) AS passing,
    count(*) FILTER (WHERE ((a11y_conformance.status)::text = 'fail'::text)) AS failing,
    count(*) FILTER (WHERE ((a11y_conformance.status)::text = 'not_tested'::text)) AS untested,
    count(*) FILTER (WHERE ((a11y_conformance.verified_by)::text = 'automated'::text)) AS automated_only,
    count(*) FILTER (WHERE ((a11y_conformance.verified_by)::text = ANY ((ARRAY['manual'::character varying, 'assistive_tech'::character varying, 'user_testing'::character varying])::text[]))) AS human_verified,
    max(a11y_conformance.checked_on) AS last_checked,
        CASE
            WHEN (count(*) FILTER (WHERE ((a11y_conformance.status)::text = 'fail'::text)) > 0) THEN 'failing'::text
            WHEN (count(*) FILTER (WHERE ((a11y_conformance.verified_by)::text <> 'automated'::text)) = 0) THEN 'automated checks only — not a conformance claim'::text
            ELSE 'verified'::text
        END AS standing
   FROM public.a11y_conformance
  GROUP BY a11y_conformance.surface, a11y_conformance.surface_type;


ALTER TABLE public.v_a11y_summary OWNER TO ebdesign_user;

--
-- Name: v_active_dispatch_blocks; Type: VIEW; Schema: public; Owner: ebdesign_user
--

CREATE VIEW public.v_active_dispatch_blocks AS
 SELECT climate_alerts.alert_code,
    climate_alerts.alert_type,
    climate_alerts.severity,
    climate_alerts.state,
    climate_alerts.districts,
    climate_alerts.headline,
    climate_alerts.recommended_action,
    climate_alerts.affects_routes,
    climate_alerts.effective_from,
    climate_alerts.effective_until
   FROM public.climate_alerts
  WHERE ((climate_alerts.cancelled_at IS NULL) AND (climate_alerts.blocks_dispatch = true) AND ((CURRENT_TIMESTAMP >= climate_alerts.effective_from) AND (CURRENT_TIMESTAMP <= climate_alerts.effective_until)));


ALTER TABLE public.v_active_dispatch_blocks OWNER TO ebdesign_user;

--
-- Name: v_active_government_schemes; Type: VIEW; Schema: public; Owner: ebdesign_user
--

CREATE VIEW public.v_active_government_schemes AS
 SELECT government_schemes.id,
    government_schemes.code,
    government_schemes.name,
    government_schemes.ministry,
    government_schemes.department,
    government_schemes.category,
    government_schemes.relevance,
    government_schemes.status,
    government_schemes.effective_from,
    government_schemes.expiry_date,
    government_schemes.verification_source,
    government_schemes.last_verified_at,
    government_schemes.last_verified_by,
    government_schemes.notes,
    government_schemes.applicable_states,
    government_schemes.created_at,
    government_schemes.updated_at
   FROM public.government_schemes
  WHERE ((government_schemes.status)::text = ANY ((ARRAY['active'::character varying, 'conditional'::character varying])::text[]));


ALTER TABLE public.v_active_government_schemes OWNER TO ebdesign_user;

--
-- Name: v_active_incidents; Type: VIEW; Schema: public; Owner: ebdesign_user
--

CREATE VIEW public.v_active_incidents AS
 SELECT ei.incident_code,
    et.name AS incident_type,
    et.category,
    ei.severity,
    ei.title,
    ei.people_at_risk,
    ei.status,
    ei.detected_at,
    (EXTRACT(epoch FROM (CURRENT_TIMESTAMP - (ei.detected_at)::timestamp with time zone)) / (60)::numeric) AS minutes_open,
    et.target_acknowledge_minutes,
    (ei.acknowledged_at IS NOT NULL) AS acknowledged,
        CASE
            WHEN ((ei.acknowledged_at IS NULL) AND ((EXTRACT(epoch FROM (CURRENT_TIMESTAMP - (ei.detected_at)::timestamp with time zone)) / (60)::numeric) > (et.target_acknowledge_minutes)::numeric)) THEN true
            ELSE false
        END AS acknowledgement_overdue,
    et.immediate_actions
   FROM (public.emergency_incidents ei
     LEFT JOIN public.emergency_types et ON ((et.id = ei.type_id)))
  WHERE ((ei.status)::text <> ALL ((ARRAY['resolved'::character varying, 'closed'::character varying])::text[]));


ALTER TABLE public.v_active_incidents OWNER TO ebdesign_user;

--
-- Name: v_active_price_locks; Type: VIEW; Schema: public; Owner: ebdesign_user
--

CREATE VIEW public.v_active_price_locks AS
 SELECT cart_price_locks.id,
    cart_price_locks.cart_id,
    cart_price_locks.user_id,
    cart_price_locks.product_id,
    cart_price_locks.quantity,
    cart_price_locks.locked_price_inr,
    cart_price_locks.market_price_at_lock_inr,
    cart_price_locks.locked_at,
    cart_price_locks.expires_at,
    (EXTRACT(epoch FROM ((cart_price_locks.expires_at)::timestamp with time zone - CURRENT_TIMESTAMP)))::integer AS seconds_remaining
   FROM public.cart_price_locks
  WHERE ((cart_price_locks.released_at IS NULL) AND (cart_price_locks.expires_at > CURRENT_TIMESTAMP));


ALTER TABLE public.v_active_price_locks OWNER TO ebdesign_user;

--
-- Name: v_ai_actor_accuracy; Type: VIEW; Schema: public; Owner: ebdesign_user
--

CREATE VIEW public.v_ai_actor_accuracy AS
 SELECT ai_outcomes.actor_id,
    ai_outcomes.actor_kind,
    count(*) AS total,
    count(*) FILTER (WHERE ((ai_outcomes.outcome_status IS NULL) OR ((ai_outcomes.outcome_status)::text = 'pending'::text))) AS unjudged,
    count(*) FILTER (WHERE ((ai_outcomes.outcome_status)::text = 'helped'::text)) AS helped,
    count(*) FILTER (WHERE ((ai_outcomes.outcome_status)::text = 'harmed'::text)) AS harmed,
    count(*) FILTER (WHERE ((ai_outcomes.outcome_status)::text = 'wrong_call'::text)) AS wrong_call,
    count(*) FILTER (WHERE ((ai_outcomes.outcome_status)::text = 'not_actioned'::text)) AS ignored,
    round(
        CASE
            WHEN (count(*) FILTER (WHERE ((ai_outcomes.outcome_status)::text = ANY ((ARRAY['helped'::character varying, 'harmed'::character varying, 'no_effect'::character varying, 'wrong_call'::character varying])::text[]))) > 0) THEN (((count(*) FILTER (WHERE ((ai_outcomes.outcome_status)::text = 'helped'::text)))::numeric / (count(*) FILTER (WHERE ((ai_outcomes.outcome_status)::text = ANY ((ARRAY['helped'::character varying, 'harmed'::character varying, 'no_effect'::character varying, 'wrong_call'::character varying])::text[]))))::numeric) * (100)::numeric)
            ELSE NULL::numeric
        END, 2) AS helpfulness_pct,
    round(avg(ai_outcomes.resolution_hours), 2) AS avg_hours_to_judge
   FROM public.ai_outcomes
  GROUP BY ai_outcomes.actor_id, ai_outcomes.actor_kind;


ALTER TABLE public.v_ai_actor_accuracy OWNER TO ebdesign_user;

--
-- Name: v_ai_agent_gate; Type: VIEW; Schema: public; Owner: ebdesign_user
--

CREATE VIEW public.v_ai_agent_gate AS
 WITH scored AS (
         SELECT p.actor_id,
            count(*) FILTER (WHERE (p.resolved_at IS NOT NULL)) AS resolved,
            avg(p.stated_confidence) FILTER (WHERE (p.resolved_at IS NOT NULL)) AS stated,
            avg(p.ape_pct) AS mean_ape,
            avg(COALESCE(r.verdict_weight, 1.0)) AS mean_weight,
            bool_or(((COALESCE(r.resolution_mode, 'observed'::character varying))::text = 'human_only'::text)) AS needs_human
           FROM (public.ai_prediction_log p
             LEFT JOIN public.ai_resolution_rules r ON (((r.prediction_type)::text = (p.prediction_type)::text)))
          GROUP BY p.actor_id
        )
 SELECT scored.actor_id,
    scored.resolved,
    round(scored.stated, 2) AS stated_confidence,
    round(((100)::numeric - scored.mean_ape), 2) AS realised_accuracy,
    round((scored.stated - ((100)::numeric - scored.mean_ape)), 2) AS calibration_gap,
    round(scored.mean_weight, 2) AS evidence_weight,
    scored.needs_human,
        CASE
            WHEN ((scored.resolved IS NULL) OR (scored.resolved < 10)) THEN 'unproven'::text
            WHEN ((scored.stated - ((100)::numeric - scored.mean_ape)) > (25)::numeric) THEN 'advisory_only'::text
            WHEN ((scored.stated - ((100)::numeric - scored.mean_ape)) > (10)::numeric) THEN 'discounted'::text
            WHEN ((scored.stated - ((100)::numeric - scored.mean_ape)) < ('-20'::integer)::numeric) THEN 'underconfident'::text
            ELSE 'trusted'::text
        END AS gate,
        CASE
            WHEN ((scored.resolved IS NULL) OR (scored.resolved < 10)) THEN 0.50
            WHEN ((scored.stated - ((100)::numeric - scored.mean_ape)) > (25)::numeric) THEN 0.25
            WHEN ((scored.stated - ((100)::numeric - scored.mean_ape)) > (10)::numeric) THEN 0.70
            ELSE 1.00
        END AS authority_multiplier
   FROM scored;


ALTER TABLE public.v_ai_agent_gate OWNER TO ebdesign_user;

--
-- Name: v_ai_approval_queue; Type: VIEW; Schema: public; Owner: ebdesign_user
--

CREATE VIEW public.v_ai_approval_queue AS
 SELECT ai_proposals.id,
    ai_proposals.domain,
    ai_proposals.proposal_type,
    ai_proposals.subject_type,
    ai_proposals.subject_id,
    ai_proposals.proposed_value,
    ai_proposals.rationale,
    ai_proposals.confidence,
    ai_proposals.created_at,
    (EXTRACT(epoch FROM (CURRENT_TIMESTAMP - (ai_proposals.created_at)::timestamp with time zone)) / (3600)::numeric) AS hours_waiting
   FROM public.ai_proposals
  WHERE ((ai_proposals.status)::text = 'proposed'::text)
  ORDER BY ai_proposals.created_at;


ALTER TABLE public.v_ai_approval_queue OWNER TO ebdesign_user;

--
-- Name: v_ai_calibration; Type: VIEW; Schema: public; Owner: ebdesign_user
--

CREATE VIEW public.v_ai_calibration AS
 SELECT ai_prediction_log.actor_id,
    ai_prediction_log.prediction_type,
    count(*) FILTER (WHERE (ai_prediction_log.resolved_at IS NOT NULL)) AS resolved,
    round(avg(ai_prediction_log.stated_confidence), 2) AS mean_stated_confidence,
    round(avg(ai_prediction_log.ape_pct), 2) AS mean_ape_pct,
    round(((100)::numeric - avg(ai_prediction_log.ape_pct)), 2) AS realised_accuracy_pct,
    round((avg(ai_prediction_log.stated_confidence) - ((100)::numeric - avg(ai_prediction_log.ape_pct))), 2) AS calibration_gap,
    ai_prediction_log.input_quality
   FROM public.ai_prediction_log
  WHERE (ai_prediction_log.resolved_at IS NOT NULL)
  GROUP BY ai_prediction_log.actor_id, ai_prediction_log.prediction_type, ai_prediction_log.input_quality;


ALTER TABLE public.v_ai_calibration OWNER TO ebdesign_user;

--
-- Name: v_ai_outcomes_pending; Type: VIEW; Schema: public; Owner: ebdesign_user
--

CREATE VIEW public.v_ai_outcomes_pending AS
 SELECT ai_outcomes.id,
    ai_outcomes.actor_id,
    ai_outcomes.actor_kind,
    ai_outcomes.signal_type,
    ai_outcomes.action,
    ai_outcomes.subject_type,
    ai_outcomes.subject_id,
    ai_outcomes.escalated,
    ai_outcomes.rationale,
    ai_outcomes.reacted_at,
    (EXTRACT(epoch FROM (CURRENT_TIMESTAMP - (ai_outcomes.reacted_at)::timestamp with time zone)) / (3600)::numeric) AS hours_unjudged
   FROM public.ai_outcomes
  WHERE ((ai_outcomes.outcome_status IS NULL) OR ((ai_outcomes.outcome_status)::text = 'pending'::text))
  ORDER BY ai_outcomes.escalated DESC, ai_outcomes.reacted_at;


ALTER TABLE public.v_ai_outcomes_pending OWNER TO ebdesign_user;

--
-- Name: v_ai_unserved_intents; Type: VIEW; Schema: public; Owner: ebdesign_user
--

CREATE VIEW public.v_ai_unserved_intents AS
 SELECT r.intent,
    r.description,
    r.required_capabilities,
    r.requires_vision,
    r.handles_pii,
    r.requires_human_review,
    'No enabled model satisfies this intent'::text AS finding
   FROM public.ai_routing_rules r
  WHERE (r.enabled AND (NOT (EXISTS ( SELECT 1
           FROM public.ai_model_registry m
          WHERE (m.enabled AND (m.capabilities @> r.required_capabilities) AND ((r.requires_vision = false) OR m.supports_vision) AND ((r.handles_pii = false) OR m.approved_for_pii))))));


ALTER TABLE public.v_ai_unserved_intents OWNER TO ebdesign_user;

--
-- Name: v_ap_ageing; Type: VIEW; Schema: public; Owner: ebdesign_user
--

CREATE VIEW public.v_ap_ageing AS
 SELECT ap_invoices.company_id,
    ap_invoices.vendor_id,
    ap_invoices.invoice_number,
    ap_invoices.invoice_date,
    ap_invoices.due_date,
    ap_invoices.total_amount,
    ap_invoices.amount_paid,
    ap_invoices.amount_due,
    ap_invoices.status,
    (CURRENT_DATE - ap_invoices.due_date) AS days_overdue,
        CASE
            WHEN (ap_invoices.amount_due <= (0)::numeric) THEN 'settled'::text
            WHEN (CURRENT_DATE <= ap_invoices.due_date) THEN 'current'::text
            WHEN ((CURRENT_DATE - ap_invoices.due_date) <= 30) THEN '1-30'::text
            WHEN ((CURRENT_DATE - ap_invoices.due_date) <= 60) THEN '31-60'::text
            WHEN ((CURRENT_DATE - ap_invoices.due_date) <= 90) THEN '61-90'::text
            ELSE '90+'::text
        END AS ageing_bucket
   FROM public.ap_invoices
  WHERE ((ap_invoices.status)::text <> ALL ((ARRAY['cancelled'::character varying, 'draft'::character varying])::text[]));


ALTER TABLE public.v_ap_ageing OWNER TO ebdesign_user;

--
-- Name: v_ar_ageing; Type: VIEW; Schema: public; Owner: ebdesign_user
--

CREATE VIEW public.v_ar_ageing AS
 SELECT ar_invoices.company_id,
    ar_invoices.customer_id,
    ar_invoices.invoice_number,
    ar_invoices.invoice_date,
    ar_invoices.due_date,
    ar_invoices.total_amount,
    ar_invoices.amount_received,
    ar_invoices.amount_due,
    ar_invoices.status,
    (CURRENT_DATE - ar_invoices.due_date) AS days_overdue,
        CASE
            WHEN (ar_invoices.amount_due <= (0)::numeric) THEN 'settled'::text
            WHEN (CURRENT_DATE <= ar_invoices.due_date) THEN 'current'::text
            WHEN ((CURRENT_DATE - ar_invoices.due_date) <= 30) THEN '1-30'::text
            WHEN ((CURRENT_DATE - ar_invoices.due_date) <= 60) THEN '31-60'::text
            WHEN ((CURRENT_DATE - ar_invoices.due_date) <= 90) THEN '61-90'::text
            ELSE '90+'::text
        END AS ageing_bucket
   FROM public.ar_invoices
  WHERE ((ar_invoices.status)::text <> ALL ((ARRAY['cancelled'::character varying, 'draft'::character varying])::text[]));


ALTER TABLE public.v_ar_ageing OWNER TO ebdesign_user;

--
-- Name: v_arp_advisable; Type: VIEW; Schema: public; Owner: ebdesign_user
--

CREATE VIEW public.v_arp_advisable AS
 SELECT c.state,
    c.district,
    c.crop_key,
    p.display_name,
    c.seasons_observed,
    c.confidence,
    (c.confidence >= 0.5) AS may_advise,
        CASE
            WHEN (c.confidence >= 0.8) THEN 'calibrated'::text
            WHEN (c.confidence >= 0.5) THEN 'usable with caveats'::text
            ELSE 'must decline — advising here would be guessing with someone else''s harvest'::text
        END AS standing
   FROM (public.arp_district_calibration c
     JOIN public.arp_crop_parameters p ON (((p.crop_key)::text = (c.crop_key)::text)));


ALTER TABLE public.v_arp_advisable OWNER TO ebdesign_user;

--
-- Name: v_arp_unexplained_basis; Type: VIEW; Schema: public; Owner: ebdesign_user
--

CREATE VIEW public.v_arp_unexplained_basis AS
 SELECT arp_basis_observations.crop_key,
    arp_basis_observations.lane,
    arp_basis_observations.observed_on,
    arp_basis_observations.farmgate_per_kg,
    arp_basis_observations.ncr_delivered_per_kg,
    arp_basis_observations.gross_basis,
    arp_basis_observations.explained_by_freight_and_loss,
    arp_basis_observations.unexplained_residual,
    round(((arp_basis_observations.unexplained_residual / NULLIF(arp_basis_observations.ncr_delivered_per_kg, (0)::numeric)) * (100)::numeric), 2) AS residual_pct_of_delivered,
        CASE
            WHEN (abs(arp_basis_observations.unexplained_residual) < (0.1 * arp_basis_observations.ncr_delivered_per_kg)) THEN 'basis fully explained by freight and loss'::text
            WHEN (arp_basis_observations.unexplained_residual > (0)::numeric) THEN 'margin beyond freight and loss — quality premium, or value the farmer cannot see'::text
            ELSE 'lane running below cost'::text
        END AS verdict,
    arp_basis_observations.data_provenance
   FROM public.arp_basis_observations
  ORDER BY (abs(arp_basis_observations.unexplained_residual)) DESC;


ALTER TABLE public.v_arp_unexplained_basis OWNER TO ebdesign_user;

--
-- Name: v_booking_curve; Type: VIEW; Schema: public; Owner: ebdesign_user
--

CREATE VIEW public.v_booking_curve AS
 SELECT booking_curve_observations.crop_key,
    booking_curve_observations.days_to_expiry,
    count(*) AS observations,
    round(avg(booking_curve_observations.pct_of_lot_sold), 2) AS mean_pct_sold,
    round(stddev_samp(booking_curve_observations.pct_of_lot_sold), 2) AS stddev_pct_sold,
    round(avg(booking_curve_observations.realised_price_inr_per_kg), 2) AS mean_realised_price,
    (count(*) >= 10) AS statistically_usable
   FROM public.booking_curve_observations
  WHERE ((booking_curve_observations.data_provenance)::text = 'real'::text)
  GROUP BY booking_curve_observations.crop_key, booking_curve_observations.days_to_expiry;


ALTER TABLE public.v_booking_curve OWNER TO ebdesign_user;

--
-- Name: v_competitive_position; Type: VIEW; Schema: public; Owner: ebdesign_user
--

CREATE VIEW public.v_competitive_position AS
 SELECT p.product_id,
    p.product_name,
    count(*) AS observations,
    count(DISTINCT p.source_name) AS competitors,
    round(min(COALESCE(p.price_per_kg_inr, p.effective_price)), 2) AS lowest_per_kg,
    round(avg(COALESCE(p.price_per_kg_inr, p.effective_price)), 2) AS mean_per_kg,
    round(max(COALESCE(p.price_per_kg_inr, p.effective_price)), 2) AS highest_per_kg,
    max(p.created_at) AS latest_observation,
    (max(p.created_at) < (CURRENT_TIMESTAMP - '7 days'::interval)) AS stale,
    round(avg(p.match_confidence), 2) AS mean_match_confidence,
    array_agg(DISTINCT p.collection_method) FILTER (WHERE (p.collection_method IS NOT NULL)) AS collection_methods
   FROM public.price_intelligence p
  GROUP BY p.product_id, p.product_name;


ALTER TABLE public.v_competitive_position OWNER TO ebdesign_user;

--
-- Name: v_contract_ready_farmers; Type: VIEW; Schema: public; Owner: ebdesign_user
--

CREATE VIEW public.v_contract_ready_farmers AS
 SELECT farmer_contract_readiness.farmer_id,
    farmer_contract_readiness.crop,
    farmer_contract_readiness.map_price_inr_per_kg,
    farmer_contract_readiness.min_lot_kg,
    farmer_contract_readiness.notice_days,
    farmer_contract_readiness.advance_required_pct,
    farmer_contract_readiness.conditions,
    farmer_contract_readiness.updated_at,
        CASE
            WHEN ((farmer_contract_readiness.map_price_inr_per_kg IS NOT NULL) AND (farmer_contract_readiness.min_lot_kg IS NOT NULL) AND (farmer_contract_readiness.notice_days IS NOT NULL)) THEN 'ready'::text
            WHEN (farmer_contract_readiness.map_price_inr_per_kg IS NOT NULL) THEN 'partial — price stated, logistics terms missing'::text
            ELSE 'not ready'::text
        END AS readiness
   FROM public.farmer_contract_readiness
  WHERE (farmer_contract_readiness.willing_to_contract IS TRUE);


ALTER TABLE public.v_contract_ready_farmers OWNER TO ebdesign_user;

--
-- Name: v_cross_economy_summary; Type: VIEW; Schema: public; Owner: ebdesign_user
--

CREATE VIEW public.v_cross_economy_summary AS
 SELECT cet.from_economy,
    cet.to_economy,
    count(*) AS transfer_count,
    sum(cet.amount) AS total_amount,
    avg(cet.amount) AS average_amount,
    min(cet.created_at) AS first_transfer,
    max(cet.created_at) AS last_transfer
   FROM public.cross_economy_transfers cet
  WHERE ((cet.status)::text = 'completed'::text)
  GROUP BY cet.from_economy, cet.to_economy
  ORDER BY (sum(cet.amount)) DESC;


ALTER TABLE public.v_cross_economy_summary OWNER TO ebdesign_user;

--
-- Name: v_farmer_repayment_signal; Type: VIEW; Schema: public; Owner: ebdesign_user
--

CREATE VIEW public.v_farmer_repayment_signal AS
 SELECT l.farmer_id,
    e.due_date,
        CASE
            WHEN (((e.status)::text = 'paid'::text) AND (e.paid_date IS NOT NULL) AND ((e.paid_date)::date <= e.due_date)) THEN 100
            WHEN ((e.status)::text = 'paid'::text) THEN 55
            ELSE 0
        END AS on_time_score
   FROM (public.emi_schedule e
     JOIN public.loans l ON ((l.id = e.loan_id)))
  WHERE (e.due_date <= CURRENT_DATE);


ALTER TABLE public.v_farmer_repayment_signal OWNER TO ebdesign_user;

--
-- Name: VIEW v_farmer_repayment_signal; Type: COMMENT; Schema: public; Owner: ebdesign_user
--

COMMENT ON VIEW public.v_farmer_repayment_signal IS 'Per-instalment on-time-repayment signal (0/55/100), EMIs already due only. Ground truth for ai_resolution_rules.farmer_credit_risk — AVG(on_time_score) over the resolution window is compared to the credit-risk score predicted at farmerCreditRiskScore() time.';


--
-- Name: v_farmer_season_pl; Type: VIEW; Schema: public; Owner: ebdesign_user
--

CREATE VIEW public.v_farmer_season_pl AS
 SELECT f.id AS farmer_id,
    r.season,
    r.year,
    sum(r.net_amount) AS revenue,
    count(DISTINCT r.id) AS sale_count,
    avg(r.price_per_kg) AS avg_price_per_kg,
    sum(r.quantity_kg) AS quantity_sold_kg,
    min(r.received_on) AS first_receipt,
    max(r.received_on) AS last_receipt
   FROM (public.farmers f
     JOIN public.farmer_revenue r ON ((r.farmer_id = f.id)))
  WHERE ((r.payment_status)::text = ANY ((ARRAY['received'::character varying, 'partial'::character varying])::text[]))
  GROUP BY f.id, r.season, r.year;


ALTER TABLE public.v_farmer_season_pl OWNER TO ebdesign_user;

--
-- Name: v_folu_deforestation_risk; Type: VIEW; Schema: public; Owner: ebdesign_user
--

CREATE VIEW public.v_folu_deforestation_risk AS
 SELECT p.state,
    p.district,
    count(*) FILTER (WHERE c.is_deforestation) AS deforestation_events,
    sum(c.area_changed_ha) FILTER (WHERE c.is_deforestation) AS area_deforested_ha,
    count(*) FILTER (WHERE (c.is_deforestation AND (NOT c.verified))) AS unverified_events,
    max(c.change_date) FILTER (WHERE c.is_deforestation) AS latest_event
   FROM (public.folu_land_parcels p
     JOIN public.folu_land_use_change c ON ((c.parcel_id = p.id)))
  GROUP BY p.state, p.district;


ALTER TABLE public.v_folu_deforestation_risk OWNER TO ebdesign_user;

--
-- Name: weather_forecasts; Type: TABLE; Schema: public; Owner: ebdesign_user
--

CREATE TABLE public.weather_forecasts (
    id bigint NOT NULL,
    station_id integer,
    district character varying(80),
    state character varying(60),
    issued_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    valid_for date NOT NULL,
    horizon_days integer NOT NULL,
    rainfall_mm numeric(8,2),
    rainfall_probability_pct numeric(5,2),
    temp_max_c numeric(5,2),
    temp_min_c numeric(5,2),
    conditions character varying(80),
    provider character varying(30) DEFAULT 'imd'::character varying NOT NULL,
    stated_confidence_pct numeric(5,2),
    actual_rainfall_mm numeric(8,2),
    actual_temp_max_c numeric(5,2),
    scored_at timestamp without time zone,
    CONSTRAINT forecast_is_not_hindcast CHECK ((valid_for >= (issued_at)::date)),
    CONSTRAINT weather_forecasts_horizon_days_check CHECK (((horizon_days >= 0) AND (horizon_days <= 30))),
    CONSTRAINT weather_forecasts_provider_check CHECK (((provider)::text = ANY ((ARRAY['imd'::character varying, 'openweather'::character varying, 'ecmwf'::character varying, 'gfs'::character varying, 'ensemble'::character varying, 'local_model'::character varying])::text[]))),
    CONSTRAINT weather_forecasts_rainfall_mm_check CHECK (((rainfall_mm IS NULL) OR (rainfall_mm >= (0)::numeric))),
    CONSTRAINT weather_forecasts_rainfall_probability_pct_check CHECK (((rainfall_probability_pct IS NULL) OR ((rainfall_probability_pct >= (0)::numeric) AND (rainfall_probability_pct <= (100)::numeric)))),
    CONSTRAINT weather_forecasts_stated_confidence_pct_check CHECK (((stated_confidence_pct IS NULL) OR ((stated_confidence_pct >= (0)::numeric) AND (stated_confidence_pct <= (100)::numeric))))
);


ALTER TABLE public.weather_forecasts OWNER TO ebdesign_user;

--
-- Name: v_forecast_accuracy; Type: VIEW; Schema: public; Owner: ebdesign_user
--

CREATE VIEW public.v_forecast_accuracy AS
 SELECT weather_forecasts.provider,
    weather_forecasts.horizon_days,
    count(*) FILTER (WHERE (weather_forecasts.scored_at IS NOT NULL)) AS scored,
    round(avg(abs((weather_forecasts.rainfall_mm - weather_forecasts.actual_rainfall_mm))), 2) AS mean_rainfall_error_mm,
    round(avg(abs((weather_forecasts.temp_max_c - weather_forecasts.actual_temp_max_c))), 2) AS mean_temp_error_c,
    round(avg(weather_forecasts.stated_confidence_pct), 2) AS mean_stated_confidence
   FROM public.weather_forecasts
  WHERE (weather_forecasts.scored_at IS NOT NULL)
  GROUP BY weather_forecasts.provider, weather_forecasts.horizon_days;


ALTER TABLE public.v_forecast_accuracy OWNER TO ebdesign_user;

--
-- Name: v_fpo_centre_pnl; Type: VIEW; Schema: public; Owner: ebdesign_user
--

CREATE VIEW public.v_fpo_centre_pnl AS
 SELECT c.id AS centre_id,
    c.centre_code,
    c.centre_name,
    c.district,
    sum(t.amount_inr) FILTER (WHERE ((t.txn_type)::text = 'sale'::text)) AS revenue_inr,
    sum(t.amount_inr) FILTER (WHERE ((t.txn_type)::text = 'procurement'::text)) AS procurement_inr,
    sum(t.amount_inr) FILTER (WHERE ((t.txn_type)::text = 'expense'::text)) AS expense_inr,
    sum(t.amount_inr) FILTER (WHERE ((t.txn_type)::text = 'wastage'::text)) AS wastage_inr,
    (COALESCE(sum(t.amount_inr) FILTER (WHERE ((t.txn_type)::text = 'sale'::text)), (0)::numeric) - COALESCE(sum(t.amount_inr) FILTER (WHERE ((t.txn_type)::text = ANY ((ARRAY['procurement'::character varying, 'expense'::character varying, 'wastage'::character varying])::text[]))), (0)::numeric)) AS net_inr,
    round(((COALESCE(sum(t.amount_inr) FILTER (WHERE ((t.txn_type)::text = 'wastage'::text)), (0)::numeric) / NULLIF(sum(t.amount_inr) FILTER (WHERE ((t.txn_type)::text = 'procurement'::text)), (0)::numeric)) * (100)::numeric), 2) AS wastage_pct_of_procurement
   FROM (public.fpo_cost_centres c
     LEFT JOIN public.fpo_centre_transactions t ON ((t.centre_id = c.id)))
  GROUP BY c.id, c.centre_code, c.centre_name, c.district;


ALTER TABLE public.v_fpo_centre_pnl OWNER TO ebdesign_user;

--
-- Name: v_freight_slot_availability; Type: VIEW; Schema: public; Owner: ebdesign_user
--

CREATE VIEW public.v_freight_slot_availability AS
 SELECT fs.slot_code,
    fl.lane_code,
    fl.origin,
    fl.destination,
    fl.distance_km,
    fs.departure_at,
    fs.total_capacity_kg,
    (fs.fpo_capacity_kg - fs.fpo_used_kg) AS fpo_available_kg,
    (fs.general_capacity_kg - fs.general_used_kg) AS general_available_kg,
        CASE
            WHEN fs.released THEN ((fs.fpo_capacity_kg - fs.fpo_used_kg) + (fs.general_capacity_kg - fs.general_used_kg))
            ELSE (fs.general_capacity_kg - fs.general_used_kg)
        END AS bookable_by_general_kg,
    fs.released,
    fs.status
   FROM (public.freight_slots fs
     JOIN public.freight_lanes fl ON (((fl.lane_code)::text = (fs.lane_code)::text)))
  WHERE ((fs.status)::text = ANY ((ARRAY['open'::character varying, 'closing'::character varying])::text[]));


ALTER TABLE public.v_freight_slot_availability OWNER TO ebdesign_user;

--
-- Name: v_landed_cost_total; Type: VIEW; Schema: public; Owner: ebdesign_user
--

CREATE VIEW public.v_landed_cost_total AS
 SELECT landed_cost_components.corridor,
    sum(landed_cost_components.min_inr_per_kg) AS min_total_inr_per_kg,
    sum(landed_cost_components.optimised_inr_per_kg) AS optimised_total_inr_per_kg,
    sum(landed_cost_components.max_inr_per_kg) AS max_total_inr_per_kg,
    count(*) AS components,
    max(landed_cost_components.as_of) AS as_of
   FROM public.landed_cost_components
  GROUP BY landed_cost_components.corridor;


ALTER TABLE public.v_landed_cost_total OWNER TO ebdesign_user;

--
-- Name: v_landed_cost_share; Type: VIEW; Schema: public; Owner: ebdesign_user
--

CREATE VIEW public.v_landed_cost_share AS
 SELECT c.corridor,
    c.sequence_no,
    c.component,
    c.optimised_inr_per_kg,
    round(((c.optimised_inr_per_kg / NULLIF(t.optimised_total_inr_per_kg, (0)::numeric)) * (100)::numeric), 2) AS pct_of_total,
    c.subsidy_scheme
   FROM (public.landed_cost_components c
     JOIN public.v_landed_cost_total t ON (((t.corridor)::text = (c.corridor)::text)))
  ORDER BY c.optimised_inr_per_kg DESC;


ALTER TABLE public.v_landed_cost_share OWNER TO ebdesign_user;

--
-- Name: v_ledger_integrity; Type: VIEW; Schema: public; Owner: ebdesign_user
--

CREATE VIEW public.v_ledger_integrity AS
 SELECT c.id,
    c.entry_ref,
    c.sequence_no,
    c.prev_hash,
    p.entry_hash AS expected_prev_hash,
    'chain broken — this entry does not follow the one before it'::text AS finding
   FROM (public.gl_ledger_chain c
     LEFT JOIN public.gl_ledger_chain p ON ((p.sequence_no = (c.sequence_no - 1))))
  WHERE ((c.sequence_no > 1) AND ((p.entry_hash IS NULL) OR ((c.prev_hash)::text <> (p.entry_hash)::text)));


ALTER TABLE public.v_ledger_integrity OWNER TO ebdesign_user;

--
-- Name: v_ledger_trial_balance; Type: VIEW; Schema: public; Owner: ebdesign_user
--

CREATE VIEW public.v_ledger_trial_balance AS
 WITH movements AS (
         SELECT gl_ledger_chain.debit_account AS account,
            gl_ledger_chain.amount AS dr,
            (0)::numeric AS cr
           FROM public.gl_ledger_chain
        UNION ALL
         SELECT gl_ledger_chain.credit_account,
            (0)::numeric AS "numeric",
            gl_ledger_chain.amount
           FROM public.gl_ledger_chain
        )
 SELECT movements.account,
    sum(movements.dr) AS total_debit,
    sum(movements.cr) AS total_credit,
    (sum(movements.dr) - sum(movements.cr)) AS balance
   FROM movements
  GROUP BY movements.account
  ORDER BY movements.account;


ALTER TABLE public.v_ledger_trial_balance OWNER TO ebdesign_user;

--
-- Name: v_ledger_trial_balance_check; Type: VIEW; Schema: public; Owner: ebdesign_user
--

CREATE VIEW public.v_ledger_trial_balance_check AS
 SELECT sum(v_ledger_trial_balance.total_debit) AS total_debit,
    sum(v_ledger_trial_balance.total_credit) AS total_credit,
    (sum(v_ledger_trial_balance.total_debit) - sum(v_ledger_trial_balance.total_credit)) AS difference,
    (sum(v_ledger_trial_balance.total_debit) = sum(v_ledger_trial_balance.total_credit)) AS balanced
   FROM public.v_ledger_trial_balance;


ALTER TABLE public.v_ledger_trial_balance_check OWNER TO ebdesign_user;

--
-- Name: v_legal_calendar; Type: VIEW; Schema: public; Owner: ebdesign_user
--

CREATE VIEW public.v_legal_calendar AS
 SELECT legal_matters.matter_code,
    legal_matters.matter_type,
    legal_matters.title,
    legal_matters.counterparty,
    legal_matters.next_hearing_date AS due_date,
    'hearing'::text AS due_type,
    legal_matters.status
   FROM public.legal_matters
  WHERE ((legal_matters.next_hearing_date IS NOT NULL) AND ((legal_matters.status)::text <> ALL ((ARRAY['closed'::character varying, 'settled'::character varying])::text[])))
UNION ALL
 SELECT legal_obligations.obligation_code AS matter_code,
    legal_obligations.source_type AS matter_type,
    legal_obligations.description AS title,
    legal_obligations.source_reference AS counterparty,
    legal_obligations.due_date,
    'obligation'::text AS due_type,
    legal_obligations.status
   FROM public.legal_obligations
  WHERE ((legal_obligations.due_date IS NOT NULL) AND ((legal_obligations.status)::text = 'open'::text));


ALTER TABLE public.v_legal_calendar OWNER TO ebdesign_user;

--
-- Name: v_model_performance; Type: VIEW; Schema: public; Owner: ebdesign_user
--

CREATE VIEW public.v_model_performance AS
 SELECT ai_invocations.model_key,
    count(*) AS calls,
    count(*) FILTER (WHERE ((ai_invocations.outcome)::text = 'success'::text)) AS successes,
    round((((count(*) FILTER (WHERE ((ai_invocations.outcome)::text = 'success'::text)))::numeric / (NULLIF(count(*), 0))::numeric) * (100)::numeric), 2) AS success_pct,
    count(*) FILTER (WHERE ai_invocations.used_fallback) AS fallback_calls,
    round(avg(ai_invocations.latency_ms), 0) AS mean_latency_ms,
    round(sum(ai_invocations.cost_inr), 2) AS total_cost_inr,
    round(avg(ai_invocations.cost_inr), 4) AS mean_cost_per_call_inr
   FROM public.ai_invocations
  GROUP BY ai_invocations.model_key;


ALTER TABLE public.v_model_performance OWNER TO ebdesign_user;

--
-- Name: v_ne_organic_status; Type: VIEW; Schema: public; Owner: ebdesign_user
--

CREATE VIEW public.v_ne_organic_status AS
 SELECT e.id,
    e.farmer_id,
    s.scheme_code,
    s.name AS scheme_name,
    e.conversion_status,
    e.area_ha,
    e.certificate_valid_to,
    e.next_inspection_due,
    ((e.certificate_valid_to IS NOT NULL) AND (e.certificate_valid_to < (CURRENT_DATE + 90))) AS certificate_expiring,
    ((e.next_inspection_due IS NOT NULL) AND (e.next_inspection_due < CURRENT_DATE)) AS inspection_overdue,
    GREATEST(((COALESCE(s.support_per_ha, (0)::numeric) * COALESCE(e.area_ha, (0)::numeric)) - COALESCE(e.support_claimed, (0)::numeric)), (0)::numeric) AS unclaimed_support
   FROM (public.ne_organic_enrolment e
     JOIN public.ne_organic_schemes s ON ((s.id = e.scheme_id)))
  WHERE ((e.conversion_status)::text <> ALL ((ARRAY['withdrawn'::character varying, 'expired'::character varying])::text[]));


ALTER TABLE public.v_ne_organic_status OWNER TO ebdesign_user;

--
-- Name: v_party_risk; Type: VIEW; Schema: public; Owner: ebdesign_user
--

CREATE VIEW public.v_party_risk AS
 SELECT party_risk_events.party_id,
    party_risk_events.party_type,
    count(*) AS events,
    count(*) FILTER (WHERE ((party_risk_events.event_type)::text = 'dispute'::text)) AS disputes,
    count(*) FILTER (WHERE ((party_risk_events.event_type)::text = 'grade_mismatch'::text)) AS grade_mismatches,
    count(*) FILTER (WHERE ((party_risk_events.event_type)::text = 'payment_default'::text)) AS payment_defaults,
    GREATEST((0)::bigint, LEAST((100)::bigint, sum(party_risk_events.weight))) AS risk_score,
        CASE
            WHEN (GREATEST((0)::bigint, LEAST((100)::bigint, sum(party_risk_events.weight))) >= 50) THEN 'high'::text
            WHEN (GREATEST((0)::bigint, LEAST((100)::bigint, sum(party_risk_events.weight))) >= 20) THEN 'medium'::text
            ELSE 'low'::text
        END AS risk_level,
    max(party_risk_events.occurred_at) AS last_event_at
   FROM public.party_risk_events
  GROUP BY party_risk_events.party_id, party_risk_events.party_type;


ALTER TABLE public.v_party_risk OWNER TO ebdesign_user;

--
-- Name: workflow_definitions; Type: TABLE; Schema: public; Owner: ebdesign_user
--

CREATE TABLE public.workflow_definitions (
    id integer NOT NULL,
    workflow_code character varying(60) NOT NULL,
    name character varying(255) NOT NULL,
    entity_type character varying(60) NOT NULL,
    description text,
    version integer DEFAULT 1 NOT NULL,
    is_active boolean DEFAULT true,
    created_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP
);


ALTER TABLE public.workflow_definitions OWNER TO ebdesign_user;

--
-- Name: workflow_instances; Type: TABLE; Schema: public; Owner: ebdesign_user
--

CREATE TABLE public.workflow_instances (
    id integer NOT NULL,
    instance_code character varying(60) NOT NULL,
    workflow_id integer NOT NULL,
    entity_type character varying(60) NOT NULL,
    entity_id character varying(100) NOT NULL,
    current_step_id integer,
    status character varying(20) DEFAULT 'running'::character varying NOT NULL,
    initiated_by uuid,
    context jsonb DEFAULT '{}'::jsonb,
    started_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP,
    completed_at timestamp without time zone,
    outcome_reason text,
    CONSTRAINT wf_rejection_needs_reason CHECK ((((status)::text <> 'rejected'::text) OR ((outcome_reason IS NOT NULL) AND (length(TRIM(BOTH FROM outcome_reason)) > 0)))),
    CONSTRAINT workflow_instances_status_check CHECK (((status)::text = ANY ((ARRAY['running'::character varying, 'waiting'::character varying, 'approved'::character varying, 'rejected'::character varying, 'cancelled'::character varying, 'expired'::character varying])::text[])))
);


ALTER TABLE public.workflow_instances OWNER TO ebdesign_user;

--
-- Name: workflow_steps; Type: TABLE; Schema: public; Owner: ebdesign_user
--

CREATE TABLE public.workflow_steps (
    id integer NOT NULL,
    workflow_id integer NOT NULL,
    step_number smallint NOT NULL,
    step_code character varying(60) NOT NULL,
    name character varying(255) NOT NULL,
    step_type character varying(20) DEFAULT 'approval'::character varying NOT NULL,
    required_role character varying(60),
    threshold_amount numeric(20,4),
    sla_hours integer,
    on_timeout character varying(20) DEFAULT 'escalate'::character varying NOT NULL,
    escalate_to_role character varying(60),
    is_skippable boolean DEFAULT false,
    CONSTRAINT wf_timeout_escalation CHECK ((((on_timeout)::text <> 'escalate'::text) OR (escalate_to_role IS NOT NULL))),
    CONSTRAINT workflow_steps_on_timeout_check CHECK (((on_timeout)::text = ANY ((ARRAY['escalate'::character varying, 'auto_approve'::character varying, 'auto_reject'::character varying, 'notify_only'::character varying])::text[]))),
    CONSTRAINT workflow_steps_step_type_check CHECK (((step_type)::text = ANY ((ARRAY['approval'::character varying, 'task'::character varying, 'notification'::character varying, 'automated'::character varying, 'decision'::character varying, 'wait'::character varying])::text[])))
);


ALTER TABLE public.workflow_steps OWNER TO ebdesign_user;

--
-- Name: v_pending_approvals; Type: VIEW; Schema: public; Owner: ebdesign_user
--

CREATE VIEW public.v_pending_approvals AS
 SELECT wi.instance_code,
    wd.name AS workflow,
    wi.entity_type,
    wi.entity_id,
    ws.name AS current_step,
    ws.required_role,
    ws.sla_hours,
    wi.started_at,
    (EXTRACT(epoch FROM (CURRENT_TIMESTAMP - (wi.started_at)::timestamp with time zone)) / (3600)::numeric) AS hours_open,
        CASE
            WHEN (ws.sla_hours IS NULL) THEN 'no_sla'::text
            WHEN ((EXTRACT(epoch FROM (CURRENT_TIMESTAMP - (wi.started_at)::timestamp with time zone)) / (3600)::numeric) > (ws.sla_hours)::numeric) THEN 'breached'::text
            ELSE 'within_sla'::text
        END AS sla_status
   FROM ((public.workflow_instances wi
     JOIN public.workflow_definitions wd ON ((wd.id = wi.workflow_id)))
     LEFT JOIN public.workflow_steps ws ON ((ws.id = wi.current_step_id)))
  WHERE ((wi.status)::text = ANY ((ARRAY['running'::character varying, 'waiting'::character varying])::text[]));


ALTER TABLE public.v_pending_approvals OWNER TO ebdesign_user;

--
-- Name: v_pii_routing_violations; Type: VIEW; Schema: public; Owner: ebdesign_user
--

CREATE VIEW public.v_pii_routing_violations AS
 SELECT i.id,
    i.invoked_at,
    i.agent_key,
    i.intent,
    i.model_key,
    m.data_residency,
    m.approved_for_pii,
    'PII sent to a model not approved for it'::text AS finding
   FROM (public.ai_invocations i
     JOIN public.ai_model_registry m ON (((m.model_key)::text = (i.model_key)::text)))
  WHERE ((i.contained_pii = true) AND (m.approved_for_pii = false));


ALTER TABLE public.v_pii_routing_violations OWNER TO ebdesign_user;

--
-- Name: v_price_lock_exposure; Type: VIEW; Schema: public; Owner: ebdesign_user
--

CREATE VIEW public.v_price_lock_exposure AS
 SELECT cart_price_locks.product_id,
    count(*) AS active_locks,
    sum(cart_price_locks.quantity) AS locked_quantity,
    sum((cart_price_locks.quantity * cart_price_locks.locked_price_inr)) AS locked_value_inr,
    sum((cart_price_locks.quantity * cart_price_locks.market_price_at_lock_inr)) AS market_value_at_lock_inr,
    sum((cart_price_locks.quantity * (cart_price_locks.market_price_at_lock_inr - cart_price_locks.locked_price_inr))) AS exposure_inr
   FROM public.cart_price_locks
  WHERE ((cart_price_locks.released_at IS NULL) AND (cart_price_locks.expires_at > CURRENT_TIMESTAMP))
  GROUP BY cart_price_locks.product_id;


ALTER TABLE public.v_price_lock_exposure OWNER TO ebdesign_user;

--
-- Name: v_public_listings; Type: VIEW; Schema: public; Owner: ebdesign_user
--

CREATE VIEW public.v_public_listings AS
 SELECT sales_listings.id,
