    sales_listings.state_of_origin,
    sales_listings.created_at
   FROM public.sales_listings
  WHERE (sales_listings.is_active = true);


ALTER TABLE public.v_public_listings OWNER TO ebdesign_user;

--
-- Name: VIEW v_public_listings; Type: COMMENT; Schema: public; Owner: ebdesign_user
--

COMMENT ON VIEW public.v_public_listings IS 'Buyer-safe projection. Deliberately excludes MAP-A floor price. Use this for all buyer-facing reads.';


--
-- Name: v_risk_heatmap; Type: VIEW; Schema: public; Owner: ebdesign_user
--

CREATE VIEW public.v_risk_heatmap AS
 SELECT risk_register.category,
    count(*) FILTER (WHERE (risk_register.residual_score >= 15)) AS critical,
    count(*) FILTER (WHERE ((risk_register.residual_score >= 8) AND (risk_register.residual_score <= 14))) AS high,
    count(*) FILTER (WHERE ((risk_register.residual_score >= 4) AND (risk_register.residual_score <= 7))) AS medium,
    count(*) FILTER (WHERE (risk_register.residual_score < 4)) AS low,
    count(*) AS total,
    count(*) FILTER (WHERE (risk_register.next_review < CURRENT_DATE)) AS overdue_review
   FROM public.risk_register
  WHERE ((risk_register.status)::text <> 'closed'::text)
  GROUP BY risk_register.category;


ALTER TABLE public.v_risk_heatmap OWNER TO ebdesign_user;

--
-- Name: v_sales_pipeline; Type: VIEW; Schema: public; Owner: ebdesign_user
--

CREATE VIEW public.v_sales_pipeline AS
 SELECT crm_opportunities.stage,
    count(*) AS deal_count,
    sum(crm_opportunities.amount) AS gross_value,
    sum(crm_opportunities.weighted_value) AS weighted_value,
    avg(crm_opportunities.probability_pct) AS avg_probability
   FROM public.crm_opportunities
  WHERE ((crm_opportunities.stage)::text <> ALL ((ARRAY['won'::character varying, 'lost'::character varying])::text[]))
  GROUP BY crm_opportunities.stage;


ALTER TABLE public.v_sales_pipeline OWNER TO ebdesign_user;

--
-- Name: v_token_integrity; Type: VIEW; Schema: public; Owner: ebdesign_user
--

CREATE VIEW public.v_token_integrity AS
 SELECT t.token_key,
    t.category,
    t.theme,
    t.references_token,
        CASE
            WHEN ((t.references_token IS NOT NULL) AND (NOT (EXISTS ( SELECT 1
               FROM public.design_tokens d
              WHERE ((d.token_key)::text = (t.references_token)::text))))) THEN 'references a token that does not exist'::text
            WHEN t.deprecated THEN ('deprecated — use '::text || (COALESCE(t.replaced_by, '(unspecified)'::character varying))::text)
            ELSE 'ok'::text
        END AS finding
   FROM public.design_tokens t;


ALTER TABLE public.v_token_integrity OWNER TO ebdesign_user;

--
-- Name: v_ui_stable_components; Type: VIEW; Schema: public; Owner: ebdesign_user
--

CREATE VIEW public.v_ui_stable_components AS
 SELECT ui_components.component_key,
    ui_components.display_name,
    ui_components.category,
    ui_components.wcag_level,
    ui_components.states,
    ui_components.variants,
    ui_components.file_path
   FROM public.ui_components
  WHERE ((ui_components.status)::text = 'stable'::text)
  ORDER BY ui_components.category, ui_components.component_key;


ALTER TABLE public.v_ui_stable_components OWNER TO ebdesign_user;

--
-- Name: v_unified_ledger_enriched; Type: VIEW; Schema: public; Owner: ebdesign_user
--

CREATE VIEW public.v_unified_ledger_enriched AS
 SELECT ul.transaction_id,
    ul.economy,
    ul.type,
    ul.amount,
    ul.currency,
    ul.description,
    ul.reference,
    ul.account_id,
    ul.counterparty_id,
    ul.category,
    ul.entry_hash,
    ul.created_at,
    ul.created_by,
    ul.reconciled_at,
    eb.total_credits AS economy_total_credits,
    eb.total_debits AS economy_total_debits,
    eb.net_balance AS economy_net_balance,
        CASE
            WHEN ((ul.economy)::text = 'north'::text) THEN 'Northern Economy'::character varying
            WHEN ((ul.economy)::text = 'south'::text) THEN 'Southern Economy'::character varying
            WHEN ((ul.economy)::text = 'east'::text) THEN 'Eastern Economy'::character varying
            WHEN ((ul.economy)::text = 'west'::text) THEN 'Western Economy'::character varying
            WHEN ((ul.economy)::text = 'central'::text) THEN 'Central Economy'::character varying
            WHEN ((ul.economy)::text = 'northeast'::text) THEN 'Northeastern Economy'::character varying
            WHEN ((ul.economy)::text = 'northwest'::text) THEN 'Northwestern Economy'::character varying
            WHEN ((ul.economy)::text = 'southeast'::text) THEN 'Southeastern Economy'::character varying
            WHEN ((ul.economy)::text = 'southwest'::text) THEN 'Southwestern Economy'::character varying
            ELSE ul.economy
        END AS economy_name
   FROM (public.unified_ledger ul
     LEFT JOIN public.economy_balances eb ON (((ul.economy)::text = (eb.economy)::text)));


ALTER TABLE public.v_unified_ledger_enriched OWNER TO ebdesign_user;

--
-- Name: weather_observations; Type: TABLE; Schema: public; Owner: ebdesign_user
--

CREATE TABLE public.weather_observations (
    id bigint NOT NULL,
    station_id integer,
    observed_on date NOT NULL,
    observed_at timestamp without time zone,
    rainfall_mm numeric(8,2),
    temp_max_c numeric(5,2),
    temp_min_c numeric(5,2),
    temp_mean_c numeric(5,2),
    humidity_pct numeric(5,2),
    wind_speed_kmph numeric(6,2),
    wind_direction_deg numeric(5,1),
    solar_radiation_mj numeric(8,2),
    source character varying(20) DEFAULT 'imd'::character varying NOT NULL,
    quality_flag character varying(20) DEFAULT 'raw'::character varying NOT NULL,
    created_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT interpolated_is_flagged CHECK ((((source)::text <> 'interpolated'::text) OR ((quality_flag)::text = 'interpolated'::text))),
    CONSTRAINT mean_inside_range CHECK (((temp_mean_c IS NULL) OR (temp_min_c IS NULL) OR (temp_max_c IS NULL) OR ((temp_mean_c >= temp_min_c) AND (temp_mean_c <= temp_max_c)))),
    CONSTRAINT temp_min_below_max CHECK (((temp_min_c IS NULL) OR (temp_max_c IS NULL) OR (temp_min_c <= temp_max_c))),
    CONSTRAINT weather_observations_humidity_pct_check CHECK (((humidity_pct IS NULL) OR ((humidity_pct >= (0)::numeric) AND (humidity_pct <= (100)::numeric)))),
    CONSTRAINT weather_observations_quality_flag_check CHECK (((quality_flag)::text = ANY ((ARRAY['raw'::character varying, 'validated'::character varying, 'suspect'::character varying, 'interpolated'::character varying, 'rejected'::character varying])::text[]))),
    CONSTRAINT weather_observations_rainfall_mm_check CHECK (((rainfall_mm IS NULL) OR (rainfall_mm >= (0)::numeric))),
    CONSTRAINT weather_observations_source_check CHECK (((source)::text = ANY ((ARRAY['imd'::character varying, 'isro'::character varying, 'openweather'::character varying, 'farm_sensor'::character varying, 'manual'::character varying, 'interpolated'::character varying])::text[]))),
    CONSTRAINT weather_observations_wind_direction_deg_check CHECK (((wind_direction_deg IS NULL) OR ((wind_direction_deg >= (0)::numeric) AND (wind_direction_deg <= (360)::numeric)))),
    CONSTRAINT weather_observations_wind_speed_kmph_check CHECK (((wind_speed_kmph IS NULL) OR (wind_speed_kmph >= (0)::numeric)))
);


ALTER TABLE public.weather_observations OWNER TO ebdesign_user;

--
-- Name: weather_stations; Type: TABLE; Schema: public; Owner: ebdesign_user
--

CREATE TABLE public.weather_stations (
    id integer NOT NULL,
    station_code character varying(40) NOT NULL,
    station_name character varying(160) NOT NULL,
    state character varying(60),
    district character varying(80),
    block character varying(80),
    latitude numeric(9,6) NOT NULL,
    longitude numeric(9,6) NOT NULL,
    elevation_m numeric(8,2),
    station_type character varying(20) DEFAULT 'imd'::character varying NOT NULL,
    operator character varying(120),
    active boolean DEFAULT true NOT NULL,
    commissioned_on date,
    created_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT station_not_null_island CHECK ((NOT ((latitude = (0)::numeric) AND (longitude = (0)::numeric)))),
    CONSTRAINT weather_stations_latitude_check CHECK (((latitude >= ('-90'::integer)::numeric) AND (latitude <= (90)::numeric))),
    CONSTRAINT weather_stations_longitude_check CHECK (((longitude >= ('-180'::integer)::numeric) AND (longitude <= (180)::numeric))),
    CONSTRAINT weather_stations_station_type_check CHECK (((station_type)::text = ANY ((ARRAY['imd'::character varying, 'awse'::character varying, 'private'::character varying, 'farm_sensor'::character varying, 'satellite_derived'::character varying, 'manual'::character varying])::text[])))
);


ALTER TABLE public.weather_stations OWNER TO ebdesign_user;

--
-- Name: v_weather_coverage; Type: VIEW; Schema: public; Owner: ebdesign_user
--

CREATE VIEW public.v_weather_coverage AS
 SELECT s.state,
    s.district,
    count(DISTINCT s.id) AS stations,
    count(o.id) AS observations,
    min(o.observed_on) AS earliest,
    max(o.observed_on) AS latest,
    (max(o.observed_on) >= (CURRENT_DATE - 7)) AS current_within_a_week,
    count(o.id) FILTER (WHERE ((o.quality_flag)::text = 'validated'::text)) AS validated_observations
   FROM (public.weather_stations s
     LEFT JOIN public.weather_observations o ON ((o.station_id = s.id)))
  WHERE s.active
  GROUP BY s.state, s.district;


ALTER TABLE public.v_weather_coverage OWNER TO ebdesign_user;

