--
-- Name: warehouse_capacity_utilization; Type: VIEW; Schema: public; Owner: ebdesign_user
--

CREATE VIEW public.warehouse_capacity_utilization AS
 SELECT wl.warehouse_id,
    count(*) AS total_locations,
    sum(
        CASE
            WHEN ((wl.status)::text = 'active'::text) THEN 1
            ELSE 0
        END) AS active_locations,
    sum(wl.capacity) AS total_capacity,
    sum(wl.current_occupancy) AS total_occupancy,
        CASE
            WHEN (sum(wl.capacity) > (0)::numeric) THEN ((sum(wl.current_occupancy) / sum(wl.capacity)) * (100)::numeric)
            ELSE (0)::numeric
        END AS utilization_percentage
   FROM public.warehouse_locations wl
  GROUP BY wl.warehouse_id;


