--
-- Name: yield_actuals; Type: TABLE; Schema: public; Owner: ebdesign_user
--

CREATE TABLE public.yield_actuals (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    farmer_id uuid NOT NULL,
    crop_id uuid,
    season character varying(30),
    year smallint,
    area_planted_ha numeric(12,4),
    quantity_harvested_kg numeric(14,3) NOT NULL,
    yield_kg_per_ha numeric(14,3) GENERATED ALWAYS AS (
CASE
    WHEN (area_planted_ha > (0)::numeric) THEN (quantity_harvested_kg / area_planted_ha)
    ELSE NULL::numeric
END) STORED,
    quantity_lost_kg numeric(14,3) DEFAULT 0,
    loss_reason character varying(60),
    measurement_basis character varying(20) DEFAULT 'farmer_reported'::character varying NOT NULL,
    harvested_on date,
    created_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT yield_actuals_area_planted_ha_check CHECK ((area_planted_ha > (0)::numeric)),
    CONSTRAINT yield_actuals_measurement_basis_check CHECK (((measurement_basis)::text = ANY ((ARRAY['weighbridge'::character varying, 'buyer_receipt'::character varying, 'farmer_reported'::character varying, 'estimated'::character varying])::text[]))),
    CONSTRAINT yield_actuals_quantity_harvested_kg_check CHECK ((quantity_harvested_kg >= (0)::numeric)),
    CONSTRAINT yield_actuals_quantity_lost_kg_check CHECK ((quantity_lost_kg >= (0)::numeric)),
    CONSTRAINT yield_actuals_year_check CHECK (((year >= 2000) AND (year <= 2100)))
);


ALTER TABLE public.yield_actuals OWNER TO ebdesign_user;

--
-- Name: yields; Type: TABLE; Schema: public; Owner: ebdesign_user
--

CREATE TABLE public.yields (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    farm_id uuid,
    crop_id uuid,
    quantity numeric(10,2),
    unit character varying(50),
    recorded_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP
);


ALTER TABLE public.yields OWNER TO ebdesign_user;

