--
-- Name: farmer_dashboard _RETURN; Type: RULE; Schema: public; Owner: ebdesign_user
--

CREATE OR REPLACE VIEW public.farmer_dashboard AS
 SELECT f.id,
    f.user_id,
    up.full_name AS farmer_name,
    f.fdi_score,
    f.fdi_grade,
    f.farm_size_hectares,
    fpo.name AS fpo_name,
    count(DISTINCT o.id) AS total_orders,
    COALESCE(sum(
        CASE
            WHEN (o.status = 'delivered'::public.order_status) THEN o.total_amount
            ELSE (0)::numeric
        END), (0)::numeric) AS total_revenue,
    COALESCE(sum(l.amount), (0)::numeric) AS total_loans,
    f.status
   FROM (((((public.farmers f
     JOIN public.users u ON ((f.user_id = u.id)))
     LEFT JOIN public.user_profiles up ON ((up.user_id = u.id)))
     LEFT JOIN public.fpos fpo ON ((f.fpo_id = fpo.id)))
     LEFT JOIN public.orders o ON ((f.user_id = o.user_id)))
     LEFT JOIN public.loans l ON ((f.id = l.farmer_id)))
  GROUP BY f.id, up.full_name, f.fdi_score, f.fdi_grade, f.farm_size_hectares, fpo.name, f.status;


--
-- Name: vehicle_status_summary _RETURN; Type: RULE; Schema: public; Owner: ebdesign_user
--

CREATE OR REPLACE VIEW public.vehicle_status_summary AS
 SELECT fv.id,
    fv.type,
    fv.registration_number,
    fv.capacity,
    fv.make,
    fv.model,
    fv.year,
    fv.driver_id,
    fv.features,
    fv.current_location,
    fv.mileage,
    fv.fuel_level,
    fv.status,
    fv.created_at,
    fv.updated_at,
    fv.last_maintenance_date,
    fv.next_maintenance_date,
    count(vm.id) AS maintenance_count,
    max(vm.scheduled_date) AS next_maintenance,
    count(DISTINCT ds.id) AS active_deliveries
   FROM ((public.fleet_vehicles fv
     LEFT JOIN public.vehicle_maintenance vm ON (((fv.id = vm.vehicle_id) AND ((vm.status)::text = 'scheduled'::text))))
     LEFT JOIN public.delivery_schedules ds ON (((fv.id = ds.vehicle_id) AND ((ds.status)::text = 'in_progress'::text))))
  GROUP BY fv.id;


